const PAGE_SIZE = 15;
const SKILLS = ["NEWBIE", "BEGINNER", "INTERMEDIATE", "UPPER_INTERMEDIATE", "ADVANCED"];
const tabLabels = { live: "Live", queue: "Queue", players: "Players", history: "History", rankings: "Rankings", fees: "Fees", settings: "Settings" } as const;
type Tab = keyof typeof tabLabels;
type QueueFilter = "ALL" | "WAITING" | "RESTING" | "INACTIVE" | "QUEUED" | "PLAYING";
type AuthUser = { id: string; username: string; role: AccountRole };
type FeePaymentFilter = "ALL" | PaymentMethod;
const FEE_PAYMENT_FILTERS: Array<[string, FeePaymentFilter]> = [["All", "ALL"], ["Cash", "CASH"], ["E-wallet", "EWALLET"], ["Other", "OTHER"]];
const EMPTY_PAYMENTS: Payment[] = [];
const feePlayerId = (player: FeeSummary["players"][number]) => player.sessionPlayerId ?? player.queuePlayerId;

function paymentFilterLabel(value: PaymentMethod) {
  return value === "EWALLET" ? "E-wallet" : value === "CASH" ? "Cash" : "Other";
}

function pretty(value: string) {
  return value.toLowerCase().split("_").map((part) => part[0]?.toUpperCase() + part.slice(1)).join(" ");
}

function formatMoney(amountMinor: number, currency = "PHP") {
  return new Intl.NumberFormat(undefined, { style: "currency", currency, minimumFractionDigits: 2 }).format(amountMinor / 100);
}

function playerDetails(player: Pick<QueuePlayer, "gender" | "skillLevel"> & Pick<QueuePlayer, "latePenaltyState">) {
  const gender = player.gender === "MALE" ? "Male" : player.gender === "FEMALE" ? "Female" : "Gender unavailable";
  const skill = player.skillLevel ? pretty(player.skillLevel) : "Skill unavailable";
  if (player.latePenaltyState) return `${gender} - ${skill} - Late ${pretty(player.latePenaltyState)}`;
  return `${gender} · ${skill}`;
}

function rotationMessage(suggestion: Suggestion) {
  if (suggestion.explanation?.cycleRestarted) return "All alternatives were reviewed; showing the best available lineup again.";
  if (suggestion.explanation?.lateArrival?.preferenceApplied && (suggestion.explanation.lateArrival.selectedPending ?? 0) > 0) return "On-time players were prioritized; a pending late-arrival player was needed to complete this lineup.";
  if (suggestion.explanation?.lateArrival?.preferenceApplied) return "On-time players were prioritized over pending late-arrival penalties.";
  if (suggestion.explanation?.fairness?.manualOverride) return "Queue Master priority applied; rotation remains active for the remaining players.";
  const penalties = suggestion.explanation?.repeatPenalties;
  if (penalties?.recentPairCount === 0) return "Fresh opponents selected.";
  if (penalties?.recentPartnerRepeats === 0) return "Recent repeats considered; partners rotated where balance allows.";
  return "Best balanced lineup under the current rotation constraints.";
}

function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : "Something went wrong. Please try again.";
}

function statusTone(status: string): "teal" | "orange" | "gray" {
  if (["WAITING", "AVAILABLE", "ACTIVE"].includes(status)) return "teal";
  if (["PLAYING", "OCCUPIED", "QUEUED"].includes(status)) return "orange";
  return "gray";
}

function StatusBadge({ status }: { status: string }) {
  return <Badge tone={statusTone(status)}>{pretty(status)}</Badge>;
}

function LatePenaltyBadge({ state }: { state?: QueuePlayer["latePenaltyState"] }) {
  if (!state) return null;
  return <Badge tone={state === "PENDING" ? "orange" : state === "SERVED" ? "gray" : "teal"}>Late · {pretty(state)}</Badge>;
}

function useRefreshInterval(enabled: boolean) {
  return enabled ? 8000 : false;
}

function LoginScreen({ onLoggedIn }: { onLoggedIn: (user: AuthUser) => void }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const login = useMutation({
    mutationFn: () => api.login(username.trim(), password),
    onSuccess: (result) => { try { window.sessionStorage.removeItem("shuttle-queue-offline-signed-out"); } catch { /* ignore storage cleanup failures */ } onLoggedIn(result.user); toast.success("Welcome back."); },
  });
  return (
    <main className="flex min-h-screen items-center justify-center px-5 py-10">
      <Card className="w-full max-w-md p-7 sm:p-9">
        <div className="mb-8 flex items-center gap-3">
          <div className="grid size-12 place-items-center rounded-2xl bg-[var(--teal)] text-white"><Zap size={23} /></div>
          <div><p className="text-xs font-bold uppercase tracking-[0.2em] text-[var(--teal)]">Shuttle Queue</p><h1 className="display text-3xl">Run the current queue.</h1></div>
        </div>
        <p className="mb-7 text-sm leading-6 text-[var(--muted)]">A calm command center for check-ins, fair matchups, courts, and results.</p>
        <form className="space-y-4" onSubmit={(event) => { event.preventDefault(); login.mutate(); }}>
          <label className="block text-sm font-semibold">Username<Input value={username} onChange={(event) => setUsername(event.target.value)} autoComplete="username" required /></label>
          <label className="block text-sm font-semibold">Password<Input value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="current-password" type="password" required /></label>
          {login.isError && <p className="rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">{errorMessage(login.error)}</p>}
          <Button type="submit" className="w-full" disabled={login.isPending}>{login.isPending ? "Signing in…" : "Sign in"}</Button>
        </form>
      </Card>
    </main>
  );
}

function OfflineBootstrap({ user, onLogout }: { user: AuthUser; onLogout: () => void }) {
  const [ready, setReady] = useState(false);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => {
    let cancelled = false;
    void (async () => {
      await saveProfile({ accountId: user.id, username: user.username, role: user.role, updatedAt: new Date().toISOString() });
      try { await syncAccount(user.id); } catch (reason) { if (!(await hasSnapshot(user.id))) { if (!cancelled) setError(errorMessage(reason)); return; } }
      if (!cancelled) setReady(true);
    })();
    return () => { cancelled = true; };
  }, [user]);
  useEffect(() => {
    const attempt = () => { if (navigator.onLine) void syncAccount(user.id).catch(() => undefined); };
    const onVisible = () => { if (document.visibilityState === "visible") attempt(); };
    window.addEventListener("online", attempt); document.addEventListener("visibilitychange", onVisible);
    const timer = window.setInterval(attempt, 60_000);
    return () => { window.removeEventListener("online", attempt); document.removeEventListener("visibilitychange", onVisible); window.clearInterval(timer); };
  }, [user.id]);
  if (error) return <main className="grid min-h-screen place-items-center px-5"><Card className="max-w-md p-6"><h1 className="display text-3xl">Download required</h1><p className="mt-2 text-sm leading-6 text-[var(--muted)]">Sign in once while online to download this account for offline use.</p><p role="alert" className="mt-4 rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">{error}</p><Button className="mt-5 w-full" onClick={() => window.location.reload()}>Try again</Button></Card></main>;
  if (!ready) return <main className="grid min-h-screen place-items-center text-sm text-[var(--muted)]">Preparing your offline workspace…</main>;
  return <AppShell user={user} onLogout={onLogout} />;
}

function EmptyState({ icon: Icon = CircleDot, title, body, action }: { icon?: typeof CircleDot; title: string; body: string; action?: React.ReactNode }) {
  return <div className="grid place-items-center rounded-3xl border border-dashed border-[var(--line)] bg-[#fbfdfb] px-6 py-12 text-center"><Icon className="mb-3 text-[var(--teal)]" size={28} /><h3 className="font-semibold">{title}</h3><p className="mt-1 max-w-sm text-sm text-[var(--muted)]">{body}</p>{action && <div className="mt-5">{action}</div>}</div>;
}

function DestructiveConfirmDialog({ title, body, confirmLabel, pending, error, secondaryLabel, onSecondary, onConfirm, onClose }: { title: string; body: string; confirmLabel: string; pending: boolean; error?: unknown; secondaryLabel?: string; onSecondary?: () => void; onConfirm: () => void; onClose: () => void }) {
  const dialogRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    dialogRef.current?.focus();
    const listener = (event: KeyboardEvent) => { if (event.key === "Escape" && !pending) onClose(); };
    window.addEventListener("keydown", listener);
    return () => window.removeEventListener("keydown", listener);
  }, [onClose, pending]);
  return <div className="fixed inset-0 z-50 grid items-end bg-[#102a2d]/45 p-0 sm:items-center sm:p-5"><div ref={dialogRef} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="danger-dialog-title" className="w-full rounded-t-3xl bg-white p-6 shadow-2xl outline-none sm:mx-auto sm:max-w-md sm:rounded-3xl"><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-2xl bg-[#fff0e4] text-[#a74646]"><AlertTriangle size={20} /></div><div><h2 id="danger-dialog-title" className="font-semibold">{title}</h2><p className="mt-2 text-sm leading-6 text-[var(--muted)]">{body}</p></div></div>{error !== undefined && error !== null && <p role="alert" className="mt-4 rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">{errorMessage(error)}</p>}<div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Button variant="quiet" disabled={pending} onClick={onClose}>Cancel</Button>{secondaryLabel && <Button variant="quiet" disabled={pending} onClick={onSecondary}>{secondaryLabel}</Button>}<Button variant="danger" disabled={pending} onClick={onConfirm}>{pending ? "Working…" : confirmLabel}</Button></div></div></div>;
}

function ChangePasswordDialog({ onClose }: { onClose: () => void }) {
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmation, setConfirmation] = useState("");
  const change = useMutation({ mutationFn: () => api.changePassword(currentPassword, newPassword), onSuccess: () => { toast.success("Password changed."); onClose(); } });
  const valid = newPassword.length >= 8 && newPassword === confirmation;
  return <div className="fixed inset-0 z-50 grid items-end bg-[#102a2d]/45 p-0 sm:items-center sm:p-5"><div role="dialog" aria-modal="true" aria-labelledby="password-dialog-title" className="w-full rounded-t-3xl bg-white p-6 shadow-2xl sm:mx-auto sm:max-w-md sm:rounded-3xl"><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-2xl bg-[#edf8f4] text-[var(--teal)]"><KeyRound size={20} /></div><div><h2 id="password-dialog-title" className="font-semibold">Change password</h2><p className="mt-1 text-sm leading-6 text-[var(--muted)]">Use at least 8 characters. Passwords are never sent by email.</p></div></div><form className="mt-5 space-y-3" onSubmit={(event) => { event.preventDefault(); change.mutate(); }}><label className="block text-sm font-semibold">Current password<Input type="password" autoComplete="current-password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} required /></label><label className="block text-sm font-semibold">New password<Input type="password" autoComplete="new-password" minLength={8} value={newPassword} onChange={(event) => setNewPassword(event.target.value)} required /></label><label className="block text-sm font-semibold">Confirm new password<Input type="password" autoComplete="new-password" minLength={8} value={confirmation} onChange={(event) => setConfirmation(event.target.value)} required /></label>{confirmation && newPassword !== confirmation && <p role="alert" className="text-sm text-[#8d4824]">Passwords do not match.</p>}{change.isError && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(change.error)}</p>}<div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Button type="button" variant="quiet" onClick={onClose} disabled={change.isPending}>Cancel</Button><Button type="submit" disabled={!valid || change.isPending}>{change.isPending ? "Saving…" : "Change password"}</Button></div></form></div></div>;
}

function AccountDeleteDialog({ account, preview, pending, error, onConfirm, onClose }: { account: AccountSummary; preview: Awaited<ReturnType<typeof api.accountDeletionPreview>>; pending: boolean; error?: unknown; onConfirm: (confirmationUsername: string, currentPassword: string) => void; onClose: () => void }) {
  const [confirmationUsername, setConfirmationUsername] = useState("");
  const [currentPassword, setCurrentPassword] = useState("");
  const deletion = preview.deletion;
  const valid = confirmationUsername === account.username && currentPassword.length > 0;
  return <div className="fixed inset-0 z-50 grid items-end overflow-y-auto bg-[#102a2d]/45 p-0 sm:items-center sm:p-5"><div role="dialog" aria-modal="true" aria-labelledby="account-delete-title" className="w-full rounded-t-3xl bg-white p-6 shadow-2xl sm:mx-auto sm:max-w-lg sm:rounded-3xl"><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-2xl bg-[#fff0e4] text-[#a74646]"><Trash2 size={20} /></div><div><h2 id="account-delete-title" className="font-semibold">Delete {account.username} permanently?</h2><p className="mt-1 text-sm leading-6 text-[var(--muted)]">This cannot be undone. The account must already be disabled.</p></div></div><div className="mt-4 grid grid-cols-2 gap-2 text-sm sm:grid-cols-4">{[["Sessions", deletion.sessionCount], ["Players", deletion.playerCount], ["Matches", deletion.matchCount], ["Payments", deletion.paymentCount]].map(([label, value]) => <div key={label} className="rounded-2xl bg-[#f7faf8] p-3"><p className="text-xs text-[var(--muted)]">{label}</p><p className="mt-1 font-semibold">{value}</p></div>)}</div><form className="mt-5 space-y-3" onSubmit={(event) => { event.preventDefault(); if (valid) onConfirm(confirmationUsername, currentPassword); }}><label className="block text-sm font-semibold">Type <span className="font-mono">{account.username}</span> to confirm<Input value={confirmationUsername} onChange={(event) => setConfirmationUsername(event.target.value)} autoComplete="off" required /></label><label className="block text-sm font-semibold">Your Super Admin password<Input type="password" autoComplete="current-password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} required /></label>{error !== undefined && error !== null && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(error)}</p>}<div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Button type="button" variant="quiet" onClick={onClose} disabled={pending}>Cancel</Button><Button type="submit" variant="danger" disabled={!valid || pending}>{pending ? "Deleting…" : "Delete permanently"}</Button></div></form></div></div>;
}

function AccountResetDialog({ account, pending, error, onConfirm, onClose }: { account: AccountSummary; pending: boolean; error?: unknown; onConfirm: (password: string) => void; onClose: () => void }) {
  const [password, setPassword] = useState("");
  const [confirmation, setConfirmation] = useState("");
  const valid = password.length >= 8 && password === confirmation;
  return <div className="fixed inset-0 z-50 grid items-end bg-[#102a2d]/45 p-0 sm:items-center sm:p-5"><div role="dialog" aria-modal="true" aria-labelledby="account-reset-title" className="w-full rounded-t-3xl bg-white p-6 shadow-2xl sm:mx-auto sm:max-w-md sm:rounded-3xl"><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-2xl bg-[#edf8f4] text-[var(--teal)]"><KeyRound size={20} /></div><div><h2 id="account-reset-title" className="font-semibold">Reset {account.username}’s password</h2><p className="mt-1 text-sm leading-6 text-[var(--muted)]">Share this new permanent password with the account owner out of band.</p></div></div><form className="mt-5 space-y-3" onSubmit={(event) => { event.preventDefault(); if (valid) onConfirm(password); }}><label className="block text-sm font-semibold">New password<Input type="password" autoComplete="new-password" minLength={8} value={password} onChange={(event) => setPassword(event.target.value)} required /></label><label className="block text-sm font-semibold">Confirm password<Input type="password" autoComplete="new-password" minLength={8} value={confirmation} onChange={(event) => setConfirmation(event.target.value)} required /></label>{confirmation && password !== confirmation && <p role="alert" className="text-sm text-[#8d4824]">Passwords do not match.</p>}{error !== undefined && error !== null && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(error)}</p>}<div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Button type="button" variant="quiet" onClick={onClose} disabled={pending}>Cancel</Button><Button type="submit" disabled={!valid || pending}>{pending ? "Resetting…" : "Reset password"}</Button></div></form></div></div>;
}

function accountRoleLabel(role: AccountRole) { return role === "SUPER_ADMIN" ? "Super Admin" : "Queue Master"; }

function AccountManagementView({ user }: { user: AuthUser }) {
  const queryClient = useQueryClient();
  const accountsQuery = useQuery({ queryKey: ["adminAccounts"], queryFn: api.adminAccounts, retry: false });
  const [online, setOnline] = useState(() => typeof navigator === "undefined" || navigator.onLine);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [passwordConfirmation, setPasswordConfirmation] = useState("");
  const [role, setRole] = useState<AccountRole>("QUEUE_MASTER");
  const [resetTarget, setResetTarget] = useState<AccountSummary | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{ account: AccountSummary; preview: Awaited<ReturnType<typeof api.accountDeletionPreview>> } | null>(null);
  const [previewingId, setPreviewingId] = useState<string | null>(null);
  useEffect(() => { const update = () => setOnline(navigator.onLine); window.addEventListener("online", update); window.addEventListener("offline", update); return () => { window.removeEventListener("online", update); window.removeEventListener("offline", update); }; }, []);
  const create = useMutation({ mutationFn: () => api.createAccount({ username: username.trim(), password, role }), onSuccess: () => { setUsername(""); setPassword(""); setPasswordConfirmation(""); queryClient.invalidateQueries({ queryKey: ["adminAccounts"] }); toast.success("Account created. Share the password securely."); } });
  const update = useMutation({ mutationFn: (input: { account: AccountSummary; body: { role?: AccountRole; status?: "ACTIVE" | "DISABLED" } }) => api.updateAccount(input.account.id, input.body, input.account.version), onSuccess: (_value, input) => { queryClient.invalidateQueries({ queryKey: ["adminAccounts"] }); toast.success(`${input.account.username} updated.`); } });
  const reset = useMutation({ mutationFn: (input: { account: AccountSummary; password: string }) => api.resetAccountPassword(input.account.id, input.password, input.account.version), onSuccess: () => { setResetTarget(null); queryClient.invalidateQueries({ queryKey: ["adminAccounts"] }); toast.success("Password reset. Share it securely."); } });
  const remove = useMutation({ mutationFn: (input: { account: AccountSummary; confirmationUsername: string; currentPassword: string }) => api.deleteAccount(input.account.id, input.confirmationUsername, input.currentPassword, input.account.version), onSuccess: () => { setDeleteTarget(null); queryClient.invalidateQueries({ queryKey: ["adminAccounts"] }); toast.success("Account and workspace deleted."); } });
  const createValid = username.trim().length > 0 && password.length >= 8 && password === passwordConfirmation && online;
  const openDelete = async (account: AccountSummary) => { setPreviewingId(account.id); try { setDeleteTarget({ account, preview: await api.accountDeletionPreview(account.id) }); } catch (reason) { toast.error(errorMessage(reason)); } finally { setPreviewingId(null); } };
  const accounts = accountsQuery.data ?? [];
  return <div className="space-y-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-sm text-[var(--muted)]">Super Admin area</p><h2 className="display text-4xl">Manage access.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[var(--muted)]">Create isolated workspaces for Queue Masters and other Super Admins. Passwords are shared manually; no email service is required.</p></div><Badge tone={online ? "teal" : "orange"}>{online ? "Online" : "Online required"}</Badge></div>{!online && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">Account administration is unavailable offline. Existing queue data remains available according to the normal offline rules.</p>}<Card><div className="flex items-center gap-2"><ShieldCheck size={18} className="text-[var(--teal)]" /><h3 className="font-semibold">Create account</h3></div><form className="mt-4 grid gap-3 lg:grid-cols-[1fr_1fr_1fr_auto] lg:items-end" onSubmit={(event) => { event.preventDefault(); if (createValid) create.mutate(); }}><label className="block text-sm font-semibold">Username<Input value={username} onChange={(event) => setUsername(event.target.value)} autoComplete="off" maxLength={80} required /></label><label className="block text-sm font-semibold">Password (8+ characters)<Input type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="new-password" minLength={8} required /></label><label className="block text-sm font-semibold">Role<Select value={role} onChange={(event) => setRole(event.target.value as AccountRole)}><option value="QUEUE_MASTER">Queue Master</option><option value="SUPER_ADMIN">Super Admin</option></Select></label><Button type="submit" disabled={!createValid || create.isPending}>{create.isPending ? "Creating…" : "Create account"}</Button></form><label className="mt-3 block text-sm font-semibold">Confirm password<Input type="password" value={passwordConfirmation} onChange={(event) => setPasswordConfirmation(event.target.value)} autoComplete="new-password" minLength={8} required /></label>{passwordConfirmation && password !== passwordConfirmation && <p role="alert" className="mt-2 text-sm text-[#8d4824]">Passwords do not match.</p>}{create.isError && <p role="alert" className="mt-3 rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(create.error)}</p>}</Card><Card className="overflow-hidden p-0"><div className="border-b border-[var(--line)] px-5 py-4"><div className="flex items-center justify-between gap-3"><div><h3 className="font-semibold">Accounts</h3><p className="mt-1 text-xs text-[var(--muted)]">{accounts.length} account{accounts.length === 1 ? "" : "s"}. Each workspace is isolated.</p></div><Badge tone="gray">{user.username}</Badge></div></div>{accountsQuery.isPending ? <p className="p-5 text-sm text-[var(--muted)]">Loading accounts…</p> : accountsQuery.isError ? <p role="alert" className="p-5 text-sm text-[#8d4824]">{errorMessage(accountsQuery.error)}{!online ? " Connect to the internet and retry." : ""}</p> : accounts.length === 0 ? <p className="p-5 text-sm text-[var(--muted)]">No accounts found.</p> : <div>{accounts.map((account) => { const self = account.id === user.id; return <div key={account.id} className="border-b border-[var(--line)] p-5 last:border-0"><div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-start"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{account.username}</p><Badge tone={account.role === "SUPER_ADMIN" ? "teal" : "gray"}>{accountRoleLabel(account.role)}</Badge><Badge tone={account.status === "ACTIVE" ? "teal" : "orange"}>{account.status === "ACTIVE" ? "Active" : "Disabled"}</Badge>{self && <Badge tone="gray">You</Badge>}</div><p className="mt-2 text-xs text-[var(--muted)]">{account.playerCount} players · {account.sessionCount} sessions · last login {account.lastLoginAt ? new Date(account.lastLoginAt).toLocaleString() : "never"}</p></div><div className="flex flex-wrap gap-2"><Button variant="quiet" className="px-3 py-1.5 text-xs" disabled={self || update.isPending || !online} onClick={() => { const nextRole: AccountRole = account.role === "SUPER_ADMIN" ? "QUEUE_MASTER" : "SUPER_ADMIN"; if (window.confirm(`Change ${account.username} to ${accountRoleLabel(nextRole)}?`)) update.mutate({ account, body: { role: nextRole } }); }}>{account.role === "SUPER_ADMIN" ? "Make Queue Master" : "Make Super Admin"}</Button><Button variant="quiet" className="px-3 py-1.5 text-xs" disabled={self || update.isPending || !online} onClick={() => { const nextStatus = account.status === "ACTIVE" ? "DISABLED" : "ACTIVE"; if (window.confirm(`${nextStatus === "DISABLED" ? "Disable" : "Enable"} ${account.username}?`)) update.mutate({ account, body: { status: nextStatus } }); }}>{account.status === "ACTIVE" ? "Disable" : "Enable"}</Button><Button variant="quiet" className="px-3 py-1.5 text-xs" disabled={self || reset.isPending || !online} onClick={() => setResetTarget(account)}><KeyRound size={14} /> Reset password</Button><Button variant="danger" className="px-3 py-1.5 text-xs" disabled={self || account.status !== "DISABLED" || previewingId === account.id || !online} onClick={() => void openDelete(account)}>{previewingId === account.id ? "Checking…" : "Delete"}</Button></div></div></div>; })}</div>}</Card>{resetTarget && <AccountResetDialog account={resetTarget} pending={reset.isPending} error={reset.isError ? reset.error : undefined} onConfirm={(nextPassword) => reset.mutate({ account: resetTarget, password: nextPassword })} onClose={() => { if (!reset.isPending) { setResetTarget(null); reset.reset(); } }} />}{deleteTarget && <AccountDeleteDialog account={deleteTarget.account} preview={deleteTarget.preview} pending={remove.isPending} error={remove.isError ? remove.error : undefined} onConfirm={(confirmationUsername, currentPassword) => remove.mutate({ account: deleteTarget.account, confirmationUsername, currentPassword })} onClose={() => { if (!remove.isPending) { setDeleteTarget(null); remove.reset(); } }} />}</div>;
}

function LiveDuration({ startedAt }: { startedAt?: string | null }) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => { const timer = window.setInterval(() => setNow(Date.now()), 1000); return () => window.clearInterval(timer); }, []);
  if (!startedAt) return <span>Just started</span>;
  const seconds = Math.max(0, Math.floor((now - new Date(startedAt).getTime()) / 1000));
  return <span data-testid="live-duration">{Math.floor(seconds / 60)}:{String(seconds % 60).padStart(2, "0")}</span>;
}

function CourtCard({ court, match, onScore, onCancel }: { court: Court; match: Match | undefined; onScore: (match: Match) => void; onCancel: (match: Match) => void }) {
  const playing = court.status === "OCCUPIED" && match;
  const teamA = match?.participants.filter((participant) => participant.team === "A").map((participant) => participant.displayName ?? "Player").join(" & ") || "Team A";
  const teamB = match?.participants.filter((participant) => participant.team === "B").map((participant) => participant.displayName ?? "Player").join(" & ") || "Team B";
  return <Card className={`relative overflow-hidden ${playing ? "border-[var(--teal)]" : ""}`}>
    <div className="flex items-start justify-between gap-3"><div className="flex items-center gap-2"><MapPinned size={17} className="text-[var(--teal)]" /><h3 className="font-semibold">{court.name}</h3></div><StatusBadge status={court.status === "OCCUPIED" ? "PLAYING" : court.status} /></div>
    {playing ? <div className="mt-6">
      <div className="rounded-2xl bg-[#edf8f4] p-4"><div className="flex items-center justify-between text-sm"><span className="font-semibold">{teamA}</span><span className="text-xs text-[var(--muted)]">vs</span><span className="text-right font-semibold">{teamB}</span></div><div className="mt-3 flex items-center gap-2 text-xs text-[var(--muted)]"><Clock3 size={14} /> <LiveDuration startedAt={match.startedAt ?? null} /> playing</div></div>
      <div className="mt-4 flex flex-col gap-2 sm:flex-row"><Button className="flex-1" onClick={() => onScore(match)}><Check size={16} /> Enter final score</Button><Button variant="quiet" className="sm:px-4" onClick={() => onCancel(match)}>Cancel match</Button></div>
    </div> : <div className="mt-7"><p className="text-sm text-[var(--muted)]">{court.status === "CLOSED" ? "This court is closed." : "Ready for the next match."}</p><div className="mt-4 h-2 rounded-full bg-[#edf2f0]"><div className={`h-full rounded-full ${court.status === "AVAILABLE" ? "w-full bg-[var(--teal)]" : "w-1/4 bg-[#c5d1cc]"}`} /></div></div>}
  </Card>;
}

function ScoreModal({ match, session, onClose, onComplete }: { match: Match; session: SessionSummary; onClose: () => void; onComplete: (games: { teamAScore: number; teamBScore: number }[]) => Promise<void> }) {
  const dialogRef = useRef<HTMLDivElement>(null);
  const [games, setGames] = useState([{ teamAScore: "", teamBScore: "" }]);
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const bestOf = session.scoring.bestOf;
  const teamA = match.participants.filter((participant) => participant.team === "A").map((participant) => participant.displayName ?? "Player").join(" & ") || "Team A";
  const teamB = match.participants.filter((participant) => participant.team === "B").map((participant) => participant.displayName ?? "Player").join(" & ") || "Team B";
  useEffect(() => {
    dialogRef.current?.focus();
    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") { onClose(); return; }
      if (event.key !== "Tab" || !dialogRef.current) return;
      const focusable = [...dialogRef.current.querySelectorAll<HTMLElement>("button, input, select, textarea, a[href]")].filter((element) => !element.hasAttribute("disabled"));
      if (!focusable.length) return;
      const first = focusable[0]!;
      const last = focusable[focusable.length - 1]!;
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    window.addEventListener("keydown", listener);
    return () => window.removeEventListener("keydown", listener);
  }, [onClose]);
  const winnerPreview = useMemo(() => { let a = 0; let b = 0; games.forEach((game) => { const left = Number(game.teamAScore); const right = Number(game.teamBScore); if (Number.isFinite(left) && Number.isFinite(right) && left !== right) left > right ? a++ : b++; }); return a === b ? "Winner will appear after valid scores" : `${a > b ? teamA : teamB} leads ${Math.max(a, b)}–${Math.min(a, b)}`; }, [games, teamA, teamB]);
  const updateGame = (index: number, field: "teamAScore" | "teamBScore", value: string) => setGames((current) => current.map((game, gameIndex) => gameIndex === index ? { ...game, [field]: value.replace(/[^0-9]/g, "").slice(0, 2) } : game));
  const submit = async () => {
    setError("");
    const parsed = games.map((game) => ({ teamAScore: Number(game.teamAScore), teamBScore: Number(game.teamBScore) }));
    if (parsed.some((game) => !Number.isInteger(game.teamAScore) || !Number.isInteger(game.teamBScore) || game.teamAScore < 0 || game.teamBScore < 0)) { setError("Enter a non-negative score for both teams."); return; }
    if (parsed.some((game) => game.teamAScore === game.teamBScore)) { setError("A game cannot end in a tie."); return; }
    if (session.scoring.scoreCap !== null && parsed.some((game) => game.teamAScore > session.scoring.scoreCap! || game.teamBScore > session.scoring.scoreCap!)) { setError(`Scores cannot exceed ${session.scoring.scoreCap}.`); return; }
    let aWins = 0; let bWins = 0; for (const game of parsed) game.teamAScore > game.teamBScore ? aWins++ : bWins++;
    const requiredWins = Math.floor(bestOf / 2) + 1;
    if (aWins < requiredWins && bWins < requiredWins) { setError(`Complete the ${bestOf === 3 ? "best-of-3 series" : "match"} before saving.`); return; }
    if (parsed.some((game) => Math.max(game.teamAScore, game.teamBScore) < session.scoring.pointsToWin && Math.max(game.teamAScore, game.teamBScore) !== session.scoring.scoreCap)) { setError(`Scores must reach ${session.scoring.pointsToWin} and win by ${session.scoring.winBy}.`); return; }
    setPending(true); try { await onComplete(parsed); } catch (completionError) { setError(errorMessage(completionError)); } finally { setPending(false); }
  };
  return <div className="fixed inset-0 z-50 grid items-end bg-[#102a2d]/45 p-0 sm:items-center sm:p-5" role="presentation"><div ref={dialogRef} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="score-dialog-title" className="max-h-[92vh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl outline-none sm:mx-auto sm:max-w-lg sm:rounded-3xl sm:p-7">
    <div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[var(--teal)]">Final result</p><h2 id="score-dialog-title" className="display mt-1 text-3xl">Record the score</h2></div><Button variant="quiet" className="px-3" aria-label="Close score dialog" onClick={onClose}><X size={18} /></Button></div>
    <div className="mt-5 rounded-2xl bg-[#edf8f4] p-4"><div className="flex items-center justify-between text-sm font-semibold"><span>{teamA}</span><span className="text-xs text-[var(--muted)]">vs</span><span className="text-right">{teamB}</span></div><p className="mt-2 text-xs text-[var(--muted)]">Race to {session.scoring.pointsToWin}, win by {session.scoring.winBy}, cap {session.scoring.scoreCap ?? "none"}, best of {bestOf}</p></div>
    <div className="mt-5 space-y-3">{games.map((game, index) => <div key={index} className="rounded-2xl border border-[var(--line)] p-3"><div className="mb-2 flex items-center justify-between"><span className="text-xs font-bold uppercase tracking-[0.12em] text-[var(--muted)]">Game {index + 1}</span>{bestOf === 3 && <span className="text-xs text-[var(--muted)]">{index === 0 ? "Required" : "Optional"}</span>}</div><div className="grid grid-cols-[1fr_auto_1fr] items-center gap-2"><Input inputMode="numeric" aria-label={`${teamA} game ${index + 1} score`} placeholder="0" value={game.teamAScore} onChange={(event) => updateGame(index, "teamAScore", event.target.value)} /><span className="text-sm text-[var(--muted)]">–</span><Input inputMode="numeric" aria-label={`${teamB} game ${index + 1} score`} placeholder="0" value={game.teamBScore} onChange={(event) => updateGame(index, "teamBScore", event.target.value)} /></div></div>)}</div>
    {bestOf === 3 && games.length < 3 && <Button variant="quiet" className="mt-3 w-full" onClick={() => setGames((current) => [...current, { teamAScore: "", teamBScore: "" }])}><Plus size={16} /> Add game</Button>}
    <p className="mt-4 rounded-2xl bg-[#f7faf8] px-4 py-3 text-sm text-[var(--muted)]">{winnerPreview}</p>{error && <p role="alert" className="mt-3 rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">{error}</p>}
    <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Button variant="quiet" onClick={onClose}>Keep playing</Button><Button onClick={submit} disabled={pending}>{pending ? "Saving…" : "Confirm final score"}</Button></div>
  </div></div>;
}

function CourtManagement({ sessionId, courts, onChanged }: { sessionId: string; courts: Court[]; onChanged: () => void }) {
  const [name, setName] = useState("");
  const create = useMutation({ mutationFn: () => api.createCourt(sessionId, name.trim()), onSuccess: () => { setName(""); onChanged(); toast.success("Court added."); } });
  const update = useMutation({ mutationFn: ({ court, status }: { court: Court; status: "AVAILABLE" | "CLOSED" }) => api.updateCourt(sessionId, court.id, { status }), onSuccess: () => { onChanged(); toast.success("Court updated."); } });
  return <Card className="border-dashed"><div className="flex items-start justify-between gap-4"><div><h3 className="font-semibold">Manage courts</h3><p className="mt-1 text-sm text-[var(--muted)]">Add courts before starting the session. Closed courts stay out of matchmaking.</p></div><MapPinned size={20} className="text-[var(--teal)]" /></div><div className="mt-5 flex flex-col gap-2 sm:flex-row"><Input value={name} onChange={(event) => setName(event.target.value)} placeholder="Court name" aria-label="New court name" /><Button disabled={!name.trim() || create.isPending} onClick={() => create.mutate()}><Plus size={16} /> Add court</Button></div>{create.isError && <p className="mt-3 text-sm text-[#8d4824]">{errorMessage(create.error)}</p>}<div className="mt-4 space-y-2">{courts.map((court) => <div key={court.id} className="flex items-center justify-between gap-3 rounded-2xl border border-[var(--line)] px-3 py-2"><div className="flex min-w-0 items-center gap-2"><span className="truncate text-sm font-semibold">{court.name}</span><Badge tone={court.status === "CLOSED" ? "gray" : court.status === "OCCUPIED" ? "orange" : "teal"}>{pretty(court.status)}</Badge></div>{court.status !== "OCCUPIED" && <Button variant="quiet" className="shrink-0 px-3 py-1.5 text-xs" disabled={update.isPending} onClick={() => update.mutate({ court, status: court.status === "CLOSED" ? "AVAILABLE" : "CLOSED" })}>{court.status === "CLOSED" ? "Open" : "Close"}</Button>}</div>)}</div></Card>;
}

function QueuedMatchCard({ match, courts, onChanged, onCancel }: { match: Match; courts: Court[]; onChanged: () => void; onCancel: (match: Match) => void }) {
  const [courtId, setCourtId] = useState("");
  const start = useMutation({ mutationFn: () => { if (!courtId) throw new Error("Select an available court first."); return api.startMatch(match.id, courtId); }, onSuccess: () => { onChanged(); toast.success("Queued match started."); } });
  const availableCourts = courts.filter((court) => court.status === "AVAILABLE");
  const teamA = match.participants.filter((participant) => participant.team === "A").map((participant) => participant.displayName ?? "Player").join(" & ") || "Team A";
  const teamB = match.participants.filter((participant) => participant.team === "B").map((participant) => participant.displayName ?? "Player").join(" & ") || "Team B";
  return <div className="rounded-2xl border border-[var(--line)] px-4 py-3 text-sm"><div className="flex items-center justify-between gap-3"><span className="font-semibold">{teamA}</span><span className="text-xs text-[var(--muted)]">vs</span><span className="text-right font-semibold">{teamB}</span></div><div className="mt-3 grid gap-2 sm:grid-cols-[1fr_auto_auto]"><label className="sr-only" htmlFor={`queued-court-${match.id}`}>Court for {teamA} versus {teamB}</label><Select id={`queued-court-${match.id}`} value={courtId} onChange={(event) => setCourtId(event.target.value)}><option value="">Select court to start</option>{availableCourts.map((court) => <option value={court.id} key={court.id}>{court.name}</option>)}</Select><Button className="px-3" disabled={!courtId || start.isPending} onClick={() => start.mutate()}>{start.isPending ? "Starting…" : "Start match"}</Button><Button variant="quiet" className="px-3" onClick={() => onCancel(match)}>Discard matchup</Button></div>{availableCourts.length === 0 && <p className="mt-2 text-xs text-[#8d4824]">No available courts right now. Finish a match or add a court first.</p>}{start.isError && <p role="alert" className="mt-2 rounded-xl bg-[#fff0e4] px-3 py-2 text-xs text-[#8d4824]">{errorMessage(start.error)}</p>}</div>;
}

function LiveView({ session, sessionId, onStartSession }: { session: SessionSummary; sessionId: string; onStartSession: () => void }) {
  const queryClient = useQueryClient();
  const [showCourts, setShowCourts] = useState(false);
  const [scoreMatch, setScoreMatch] = useState<Match | null>(null);
  const [discardMatch, setDiscardMatch] = useState<Match | null>(null);
  const courtsQuery = useQuery({ queryKey: ["courts", sessionId], queryFn: () => api.courts(sessionId), refetchInterval: useRefreshInterval(session.status === "ACTIVE") });
  const matchesQuery = useQuery({ queryKey: ["matches", sessionId], queryFn: () => api.matches(sessionId), refetchInterval: useRefreshInterval(session.status === "ACTIVE") });
  const invalidateOperations = () => { ["courts", "matches", "queue", "rankings", "history"].forEach((key) => queryClient.invalidateQueries({ queryKey: [key, sessionId] })); queryClient.invalidateQueries({ queryKey: ["playerHistory", sessionId] }); queryClient.invalidateQueries({ queryKey: ["sessions"] }); };
  const complete = async (games: { teamAScore: number; teamBScore: number }[]) => { if (!scoreMatch) return; await api.completeMatch(scoreMatch.id, games); setScoreMatch(null); invalidateOperations(); toast.success("Result saved. Court is available again."); };
  const discard = useMutation({ mutationFn: () => { if (!discardMatch) throw new Error("Select a match to discard."); return api.cancelMatch(discardMatch.id); }, onSuccess: () => { setDiscardMatch(null); invalidateOperations(); toast.success("Match discarded. Players are back in Waiting."); } });
  const requestDiscard = (match: Match) => { discard.reset(); setDiscardMatch(match); };
  const courts = courtsQuery.data ?? [];
  const matches = matchesQuery.data ?? [];
  const activeMatches = matches.filter((match) => match.status === "IN_PROGRESS");
  const queuedMatches = matches.filter((match) => match.status === "QUEUED");
  const error = courtsQuery.error ?? matchesQuery.error;
  return <div className="space-y-5">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm text-[var(--muted)]">Live operations</p><h2 className="display text-4xl">Courts at a glance.</h2></div><div className="flex flex-wrap gap-2"><Badge tone="teal">{courts.filter((court) => court.status === "AVAILABLE").length} available</Badge><Badge tone="orange">{activeMatches.length} playing</Badge><Badge tone="gray">{courts.filter((court) => court.status === "CLOSED").length} closed</Badge><Button variant="quiet" className="px-3" title="Refresh live data" aria-label="Refresh live data" onClick={() => invalidateOperations()}><RefreshCw size={16} /></Button></div></div>
    {session.status === "DRAFT" && <Card className="border-[#f6c49f] bg-[#fffaf5]"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">Draft session</p><p className="mt-1 text-sm text-[var(--muted)]">Add at least one court, then start the session to enable matchmaking.</p></div><Button onClick={onStartSession} disabled={courts.length === 0}><Play size={16} /> Start session</Button></div></Card>}
    {error && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">{errorMessage(error)}</p>}
    {courtsQuery.isPending ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><div className="h-56 animate-pulse rounded-3xl bg-white" /><div className="h-56 animate-pulse rounded-3xl bg-white" /></div> : courts.length === 0 ? <EmptyState icon={MapPinned} title="No courts yet" body="Create your first court to make the live board useful." action={<Button onClick={() => setShowCourts(true)}><Plus size={16} /> Manage courts</Button>} /> : <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{courts.map((court) => <CourtCard key={court.id} court={court} match={matches.find((match) => match.id === court.currentMatchId)} onScore={setScoreMatch} onCancel={requestDiscard} />)}</div>}
     {queuedMatches.length > 0 && <Card><div className="flex items-center justify-between gap-3"><div><h3 className="font-semibold">Awaiting a court</h3><p className="mt-1 text-sm text-[var(--muted)]">Choose an available court to start a queued matchup, or discard it without recording a result.</p></div><Badge tone="orange">{queuedMatches.length}</Badge></div><div className="mt-4 grid gap-2">{queuedMatches.map((match) => <QueuedMatchCard key={match.id} match={match} courts={courts} onChanged={invalidateOperations} onCancel={requestDiscard} />)}</div></Card>}
    <div className="flex items-center justify-between gap-3"><div><h3 className="font-semibold">Court setup</h3><p className="mt-1 text-sm text-[var(--muted)]">Keep operations focused; management is tucked away until you need it.</p></div><Button variant="quiet" onClick={() => setShowCourts((value) => !value)}><SlidersHorizontal size={16} /> {showCourts ? "Hide management" : "Manage courts"}<ChevronDown className={showCourts ? "rotate-180 transition" : "transition"} size={15} /></Button></div>
    {showCourts && <CourtManagement sessionId={sessionId} courts={courts} onChanged={() => { invalidateOperations(); }} />}
    {scoreMatch && <ScoreModal match={scoreMatch} session={session} onClose={() => setScoreMatch(null)} onComplete={complete} />}
    {discardMatch && <DestructiveConfirmDialog title="Discard this matchup?" body="This permanently removes the queued or playing match without creating a result or history entry. Rankings, statistics, and rotation history are unchanged. Players return to their previous waiting positions and any occupied court is released." confirmLabel="Discard match" pending={discard.isPending} error={discard.error} onConfirm={() => discard.mutate()} onClose={() => { if (!discard.isPending) { discard.reset(); setDiscardMatch(null); } }} />}
  </div>;
}

function waitMinutes(player: SessionPlayer, serverTime?: string) {
  if (!player.queueEnteredAt) return "—";
  const end = serverTime ? new Date(serverTime).getTime() : Date.now();
  return `${Math.max(0, Math.floor((end - new Date(player.queueEnteredAt).getTime()) / 60000))}m`;
}

function PlayerQueueRow({ player, sessionId, onChanged }: { player: SessionPlayer; sessionId: string; onChanged: () => void }) {
  const mutation = useMutation({ mutationFn: async (action: "checkIn" | "checkOut" | "rest" | "resume") => { if (action === "checkIn") return api.checkIn(sessionId, player.id); if (action === "checkOut") return api.checkOut(sessionId, player.id); if (action === "rest") return api.restPlayer(sessionId, player.id); return api.resumePlayer(sessionId, player.id); }, onSuccess: () => { onChanged(); } });
  const waive = useMutation({ mutationFn: () => api.waiveLatePenalty(sessionId, player.id, player.version), onSuccess: () => { onChanged(); toast.success(`${player.displayName}'s late penalty was waived.`); } });
  const action = player.status === "INACTIVE" || player.status === "CHECKED_OUT" ? { label: "Check in", intent: "checkIn" as const } : player.status === "WAITING" ? { label: "Rest", intent: "rest" as const } : player.status === "RESTING" ? { label: "Resume", intent: "resume" as const } : player.status === "PLAYING" || player.status === "QUEUED" ? null : { label: "Check out", intent: "checkOut" as const };
  return <div className="grid grid-cols-[minmax(140px,1.4fr)_70px_112px_56px_56px_92px_auto] items-center gap-3 border-b border-[var(--line)] px-3 py-3 text-sm last:border-0 max-md:grid-cols-[minmax(0,1fr)_auto] max-md:gap-y-2"><div className="min-w-0"><p className="truncate font-semibold">{player.displayName}</p><p className="text-xs text-[var(--muted)]">{player.gender === "MALE" ? "Male" : "Female"}</p><div className="mt-1"><LatePenaltyBadge state={player.latePenaltyState} /></div></div><span className="text-xs text-[var(--muted)] max-md:hidden">{pretty(player.skillLevel)}</span><span className="text-xs text-[var(--muted)] max-md:hidden">{player.matchesPlayed}</span><span className="text-xs text-[var(--muted)] max-md:hidden">{waitMinutes(player)}</span><span className="max-md:justify-self-end"><StatusBadge status={player.status} /></span><span className="text-xs text-[var(--muted)] max-md:hidden">{player.wins}W / {player.losses}L</span><div className="flex flex-wrap justify-end gap-2 max-md:col-span-2 max-md:row-start-2 max-md:w-full max-md:border-t max-md:border-[var(--line)] max-md:pt-2">{action && <Button variant="quiet" className="px-3 py-1.5 text-xs" disabled={mutation.isPending || waive.isPending} onClick={() => mutation.mutate(action.intent)}>{action.label}</Button>}{player.latePenaltyState === "PENDING" && <Button variant="quiet" className="px-3 py-1.5 text-xs" disabled={waive.isPending || mutation.isPending} onClick={() => { if (window.confirm(`Waive ${player.displayName}'s one-time late penalty?`)) waive.mutate(); }}>Waive</Button>}{(mutation.isError || waive.isError) && <p className="mt-1 w-full text-xs text-[#8d4824]">{errorMessage(mutation.error ?? waive.error)}</p>}</div></div>;
}

function ManualPlayerPicker({ team, players, selectedIds, onSelect, onClose }: { team: "A" | "B"; players: SessionPlayer[]; selectedIds: Set<string>; onSelect: (player: SessionPlayer) => void; onClose: () => void }) {
  const [search, setSearch] = useState("");
  const dialogRef = useRef<HTMLDivElement>(null);
  const eligible = useMemo(() => { const needle = search.trim().toLowerCase(); return players.filter((player) => !selectedIds.has(player.id) && (!needle || `${player.displayName} ${player.gender} ${player.skillLevel}`.toLowerCase().includes(needle))); }, [players, search, selectedIds]);
  useEffect(() => { dialogRef.current?.focus(); const listener = (event: KeyboardEvent) => { if (event.key === "Escape") { onClose(); return; } if (event.key !== "Tab" || !dialogRef.current) return; const focusable = [...dialogRef.current.querySelectorAll<HTMLElement>("button, input, select, textarea, a[href]")].filter((element) => !element.hasAttribute("disabled")); if (!focusable.length) return; const first = focusable[0]!; const last = focusable[focusable.length - 1]!; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }; window.addEventListener("keydown", listener); return () => window.removeEventListener("keydown", listener); }, [onClose]);
  return <div className="fixed inset-0 z-50 grid items-end bg-[#102a2d]/45 p-0 sm:items-center sm:p-5"><div ref={dialogRef} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="manual-picker-title" className="max-h-[85vh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl outline-none sm:mx-auto sm:max-w-lg sm:rounded-3xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[var(--teal)]">Manual matchup</p><h2 id="manual-picker-title" className="display mt-1 text-3xl">Choose Team {team} player</h2></div><Button variant="quiet" className="px-3" aria-label="Close player picker" onClick={onClose}><X size={18} /></Button></div><label className="mt-5 block text-sm font-semibold">Search waiting players<Input autoFocus value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search by name, gender, or skill" /></label><div className="mt-4 space-y-2">{eligible.length === 0 ? <EmptyState icon={UsersRound} title="No eligible players" body="Only waiting players not already on either team can be added." /> : eligible.map((player) => <button type="button" key={player.id} className="focus-ring flex w-full items-center gap-3 rounded-2xl border border-[var(--line)] p-3 text-left hover:border-[var(--teal)]" onClick={() => onSelect(player)}><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{player.displayName}</span><span className="block text-xs text-[var(--muted)]">{player.gender === "MALE" ? "Male" : "Female"} · {pretty(player.skillLevel)} · {player.matchesPlayed} games · {waitMinutes(player)} waiting</span></span><Plus size={17} className="shrink-0 text-[var(--teal)]" /></button>)}</div></div></div>;
}

function LegacyMatchmakerPanel({ sessionId, queue, courts, onChanged }: { sessionId: string; queue: QueueState; courts: Court[]; onChanged: () => void }) {
  const [panelMode, setPanelMode] = useState<"suggested" | "manual">("suggested");
  const [mode, setMode] = useState("BALANCED");
  const [suggestion, setSuggestion] = useState<Suggestion | null>(null);
  const [courtId, setCourtId] = useState("");
  const [manualTeamA, setManualTeamA] = useState<string[]>([]);
  const [manualTeamB, setManualTeamB] = useState<string[]>([]);
  const [pickerTeam, setPickerTeam] = useState<"A" | "B" | null>(null);
  const [suggestionScope, setSuggestionScope] = useState("");
  const [suggestionCycle, setSuggestionCycle] = useState<{ scope: string; keys: string[] }>({ scope: "", keys: [] });
  const manualPlayers = queue.waiting;
  const waitingFingerprint = useMemo(() => `${queue.lateArrivalCutoffAt ?? ""}|${queue.waiting.map((player) => `${player.id}:${player.matchesPlayed}:${player.queueEnteredAt ?? ""}:${player.latePenaltyState ?? ""}`).sort().join("|")}`, [queue.lateArrivalCutoffAt, queue.waiting]);
  const cycleScope = `${mode}|${waitingFingerprint}`;
  const excludedSuggestionKeys = suggestionCycle.scope === cycleScope ? suggestionCycle.keys : [];
  const visibleSuggestion = suggestion && suggestionScope === cycleScope ? suggestion : null;
  const suggest = useMutation({ mutationFn: () => api.suggestions(sessionId, mode, excludedSuggestionKeys), onSuccess: (result) => { const nextSuggestion = result.suggestion; if (nextSuggestion) { setSuggestion(nextSuggestion); setSuggestionScope(cycleScope); setSuggestionCycle((current) => { const keys = result.cycleRestarted || current.scope !== cycleScope ? [] : current.keys; return { scope: cycleScope, keys: [...new Set([...keys, nextSuggestion.key])].slice(-50) }; }); setCourtId(""); } else toast.message(result.noMatch?.message ?? "No valid group is available yet."); }, onError: (error) => toast.error(errorMessage(error)) });
  const startSuggestion = useMutation({ mutationFn: () => { if (!visibleSuggestion || !courtId) throw new Error("Select an available court first."); return api.startSuggestedMatch(sessionId, { teamA: visibleSuggestion.teamA.map((player) => player.id), teamB: visibleSuggestion.teamB.map((player) => player.id), courtId, suggestionToken: visibleSuggestion.token }); }, onSuccess: () => { setSuggestion(null); setSuggestionScope(""); setSuggestionCycle({ scope: "", keys: [] }); setCourtId(""); onChanged(); toast.success("Match started."); } });
  const selectedIds = useMemo(() => new Set([...manualTeamA, ...manualTeamB]), [manualTeamA, manualTeamB]);
  const manualReady = manualTeamA.length > 0 && manualTeamA.length === manualTeamB.length && [1, 2].includes(manualTeamA.length);
  const manualCreate = useMutation({ mutationFn: ({ startNow }: { startNow: boolean }) => { if (!manualReady) throw new Error("Choose one player per team for singles or two per team for doubles."); if (startNow && !courtId) throw new Error("Select an available court first."); return startNow ? api.startManualMatch(sessionId, manualTeamA, manualTeamB, courtId) : api.queueManualMatch(sessionId, manualTeamA, manualTeamB); }, onSuccess: (_match, variables) => { setManualTeamA([]); setManualTeamB([]); setCourtId(""); onChanged(); toast.success(variables.startNow ? "Match started." : "Match queued."); } });
  const availableCourts = courts.filter((court) => court.status === "AVAILABLE");
  const addPlayer = (player: SessionPlayer) => { if (pickerTeam === "A" && manualTeamA.length < 2) setManualTeamA((current) => [...current, player.id]); if (pickerTeam === "B" && manualTeamB.length < 2) setManualTeamB((current) => [...current, player.id]); setPickerTeam(null); };
  const removePlayer = (team: "A" | "B", id: string) => team === "A" ? setManualTeamA((current) => current.filter((playerId) => playerId !== id)) : setManualTeamB((current) => current.filter((playerId) => playerId !== id));
  const teamPlayers = (ids: string[]) => ids.map((id) => manualPlayers.find((player) => player.id === id)).filter((player): player is SessionPlayer => Boolean(player)).map((player) => player.latePenaltyState ? { ...player, displayName: `${player.displayName} · Late ${pretty(player.latePenaltyState)}` } : player);
  const changeMode = (nextMode: string) => { if (nextMode === mode) return; setMode(nextMode); setSuggestion(null); setSuggestionScope(""); setSuggestionCycle({ scope: "", keys: [] }); setCourtId(""); };
  return <Card className="h-fit lg:sticky lg:top-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[var(--teal)]">Matchmaker</p><h3 className="display mt-1 text-3xl">Make the next match.</h3></div><Sparkles className="text-[var(--orange)]" size={22} /></div><p className="mt-2 text-sm leading-6 text-[var(--muted)]">Use a fair suggestion or choose a singles/doubles lineup yourself. A saved lineup can wait for a court.</p><div className="mt-5 grid grid-cols-2 rounded-2xl bg-[#f1f5f2] p-1"><button type="button" className={`focus-ring rounded-xl px-3 py-2 text-sm font-semibold ${panelMode === "suggested" ? "bg-white text-[var(--teal-dark)] shadow-sm" : "text-[var(--muted)]"}`} onClick={() => setPanelMode("suggested")}>Suggested</button><button type="button" className={`focus-ring rounded-xl px-3 py-2 text-sm font-semibold ${panelMode === "manual" ? "bg-white text-[var(--teal-dark)] shadow-sm" : "text-[var(--muted)]"}`} onClick={() => setPanelMode("manual")}>Manual</button></div>
    {panelMode === "suggested" ? <><label className="mt-5 block text-sm font-semibold">Match mode<Select value={mode} onChange={(event) => changeMode(event.target.value)}><option value="BALANCED">Balanced</option><option value="MIXED_DOUBLES">Mixed doubles</option><option value="SAME_GENDER">Same gender</option><option value="SAME_SKILL">Same skill</option><option value="OPEN">Open</option></Select></label><Button className="mt-3 w-full" onClick={() => suggest.mutate()} disabled={suggest.isPending || queue.waiting.length < 4}>{suggest.isPending ? "Finding a fair group…" : visibleSuggestion ? "Try another lineup" : "Suggest lineup"}</Button>{queue.waiting.length < 4 && <p className="mt-2 text-xs text-[var(--muted)]">Need four waiting players. There are {queue.waiting.length} ready.</p>}{visibleSuggestion && <div className="mt-5 space-y-4 border-t border-[var(--line)] pt-5"><div className="grid grid-cols-2 gap-2"><div className="rounded-2xl bg-[#edf8f4] p-3"><p className="text-xs font-bold uppercase text-[var(--teal)]">Team A</p><div className="mt-2 space-y-2 text-sm">{visibleSuggestion.teamA.map((player) => <div key={player.id} className="min-w-0"><p className="truncate font-semibold">{player.displayName || "Player"}</p><p className="truncate text-xs text-[var(--muted)]">{playerDetails(player)}</p></div>)}</div><p className="mt-2 text-xs text-[var(--muted)]">{visibleSuggestion.teamATotal} strength</p></div><div className="rounded-2xl bg-[#fff4ec] p-3"><p className="text-xs font-bold uppercase text-[#a85b2b]">Team B</p><div className="mt-2 space-y-2 text-sm">{visibleSuggestion.teamB.map((player) => <div key={player.id} className="min-w-0"><p className="truncate font-semibold">{player.displayName || "Player"}</p><p className="truncate text-xs text-[var(--muted)]">{playerDetails(player)}</p></div>)}</div><p className="mt-2 text-xs text-[var(--muted)]">{visibleSuggestion.teamBTotal} strength</p></div></div><p className="text-xs text-[var(--muted)]">{rotationMessage(visibleSuggestion)}</p><label className="block text-sm font-semibold">Court required<Select value={courtId} onChange={(event) => setCourtId(event.target.value)}><option value="">Select an available court</option>{availableCourts.map((court) => <option value={court.id} key={court.id}>{court.name}</option>)}</Select></label>{availableCourts.length === 0 && <p className="text-xs text-[#8d4824]">No available courts. Finish a match or add a court before starting.</p>}{!courtId && availableCourts.length > 0 && <p className="text-xs text-[var(--muted)]">Choose an available court above to enable Start match.</p>}{startSuggestion.isError && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(startSuggestion.error)}</p>}<div className="flex gap-2"><Button variant="quiet" className="flex-1" onClick={() => setSuggestion(null)}>Discard</Button><Button className="flex-1" onClick={() => startSuggestion.mutate()} disabled={!courtId || startSuggestion.isPending}>{startSuggestion.isPending ? "Starting…" : "Start match"}</Button></div></div>}</> : <div className="mt-5 space-y-4 border-t border-[var(--line)] pt-5"><div className="grid grid-cols-2 gap-2"><div className="rounded-2xl border border-[var(--line)] bg-[#edf8f4] p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold uppercase text-[var(--teal)]">Team A</p><Badge tone="teal">{manualTeamA.length}/2</Badge></div><div className="mt-3 space-y-2">{teamPlayers(manualTeamA).map((player) => <div key={player.id} className="flex items-center gap-1 rounded-xl bg-white px-2 py-2 text-sm"><span className="min-w-0 flex-1 truncate">{player.displayName}</span><button type="button" className="focus-ring rounded-full p-1 text-[var(--muted)] hover:text-[#a74646]" aria-label={`Remove ${player.displayName} from Team A`} onClick={() => removePlayer("A", player.id)}><X size={14} /></button></div>)}{manualTeamA.length < 2 && <Button variant="quiet" className="w-full px-2 py-1.5 text-xs" onClick={() => setPickerTeam("A")}><Plus size={14} /> Add player</Button>}</div></div><div className="rounded-2xl border border-[var(--line)] bg-[#fff4ec] p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold uppercase text-[#a85b2b]">Team B</p><Badge tone="orange">{manualTeamB.length}/2</Badge></div><div className="mt-3 space-y-2">{teamPlayers(manualTeamB).map((player) => <div key={player.id} className="flex items-center gap-1 rounded-xl bg-white px-2 py-2 text-sm"><span className="min-w-0 flex-1 truncate">{player.displayName}</span><button type="button" className="focus-ring rounded-full p-1 text-[var(--muted)] hover:text-[#a74646]" aria-label={`Remove ${player.displayName} from Team B`} onClick={() => removePlayer("B", player.id)}><X size={14} /></button></div>)}{manualTeamB.length < 2 && <Button variant="quiet" className="w-full px-2 py-1.5 text-xs" onClick={() => setPickerTeam("B")}><Plus size={14} /> Add player</Button>}</div></div></div><p className="text-xs text-[var(--muted)]">Choose one player per team for singles, or two per team for doubles.</p><label className="block text-sm font-semibold">Court for immediate start<Select value={courtId} onChange={(event) => setCourtId(event.target.value)}><option value="">No court selected</option>{availableCourts.map((court) => <option value={court.id} key={court.id}>{court.name}</option>)}</Select></label>{availableCourts.length === 0 && <p className="text-xs text-[#8d4824]">No available courts. You can still queue this matchup.</p>}{manualCreate.isError && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(manualCreate.error)}</p>}<div className="flex flex-col gap-2"><Button onClick={() => manualCreate.mutate({ startNow: true })} disabled={!manualReady || !courtId || manualCreate.isPending}>{manualCreate.isPending ? "Starting…" : "Start match"}</Button><Button variant="quiet" onClick={() => manualCreate.mutate({ startNow: false })} disabled={!manualReady || manualCreate.isPending}>Queue matchup</Button></div></div>}
    {pickerTeam && <ManualPlayerPicker team={pickerTeam} players={manualPlayers} selectedIds={selectedIds} onSelect={addPlayer} onClose={() => setPickerTeam(null)} />}
  </Card>;
}

type SuggestionTeam = "A" | "B";
type SuggestionDraft = { teamA: string[]; teamB: string[] };
type SuggestionPickerTarget = { team: SuggestionTeam; slot: number };

function strengthValue(player: Pick<SessionPlayer, "skillWeight" | "skillLevel">) {
  return player.skillWeight ?? Math.max(0, SKILLS.indexOf(player.skillLevel) + 1);
}

function remainingSuggestionTime(expiresAt: number, now: number) {
  const remaining = Math.max(0, expiresAt - now);
  if (remaining === 0) return "Suggestion expired";
  const minutes = Math.floor(remaining / 60000);
  const seconds = Math.floor((remaining % 60000) / 1000).toString().padStart(2, "0");
  return `Valid for ${minutes}:${seconds}`;
}

function SuggestedPlayerPicker({
  target,
  currentPlayer,
  opponents,
  players,
  selectedIds,
  serverTime,
  onReplace,
  onSwap,
  onClose,
}: {
  target: SuggestionPickerTarget;
  currentPlayer: SessionPlayer | undefined;
  opponents: { player: SessionPlayer | undefined; target: SuggestionPickerTarget }[];
  players: SessionPlayer[];
  selectedIds: Set<string>;
  serverTime: string;
  onReplace: (player: SessionPlayer) => void;
  onSwap: (target: SuggestionPickerTarget) => void;
  onClose: () => void;
}) {
  const [search, setSearch] = useState("");
  const dialogRef = useRef<HTMLDivElement>(null);
  const eligible = useMemo(() => {
    const needle = search.trim().toLowerCase();
    return players.filter((player) => !selectedIds.has(player.id) && (!needle || `${player.displayName} ${player.gender} ${player.skillLevel}`.toLowerCase().includes(needle)));
  }, [players, search, selectedIds]);
  useEffect(() => {
    dialogRef.current?.focus();
    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") { onClose(); return; }
      if (event.key !== "Tab" || !dialogRef.current) return;
      const focusable = [...dialogRef.current.querySelectorAll<HTMLElement>("button, input, select, textarea, a[href]")].filter((element) => !element.hasAttribute("disabled"));
      if (!focusable.length) return;
      const first = focusable[0]!;
      const last = focusable[focusable.length - 1]!;
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    window.addEventListener("keydown", listener);
    return () => window.removeEventListener("keydown", listener);
  }, [onClose]);
  return <div className="fixed inset-0 z-50 grid items-end bg-[#102a2d]/45 p-0 sm:items-center sm:p-5"><div ref={dialogRef} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="suggestion-picker-title" className="max-h-[88vh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl outline-none sm:mx-auto sm:max-w-lg sm:rounded-3xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[var(--teal)]">Edit suggested lineup</p><h2 id="suggestion-picker-title" className="display mt-1 text-3xl">Team {target.team} player {target.slot + 1}</h2><p className="mt-1 text-sm text-[var(--muted)]">{currentPlayer?.displayName ?? "Unavailable player"}</p></div><Button variant="quiet" className="px-3" aria-label="Close lineup editor" onClick={onClose}><X size={18} /></Button></div>{opponents.length > 0 && <div className="mt-5"><p className="text-sm font-semibold">Swap with an opposing player</p><div className="mt-2 space-y-2">{opponents.map(({ player, target: opponentTarget }) => <button type="button" key={`${opponentTarget.team}-${opponentTarget.slot}`} className="focus-ring flex w-full items-center gap-3 rounded-2xl border border-[var(--line)] p-3 text-left hover:border-[var(--teal)] disabled:cursor-not-allowed disabled:opacity-50" disabled={!player} onClick={() => onSwap(opponentTarget)}><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{player?.displayName ?? "Unavailable player"}</span><span className="block text-xs text-[var(--muted)]">{player ? `${playerDetails(player)} · ${player.matchesPlayed} games` : "No longer waiting"}</span></span><Zap size={16} className="shrink-0 text-[var(--orange)]" /></button>)}</div></div>}<label className="mt-5 block text-sm font-semibold">Replace with another waiting player<Input autoFocus value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search by name, gender, or skill" /></label><div className="mt-3 space-y-2">{eligible.length === 0 ? <EmptyState icon={UsersRound} title="No eligible players" body="Only waiting players not already in this lineup can replace the slot." /> : eligible.map((player) => <button type="button" key={player.id} className="focus-ring flex w-full items-center gap-3 rounded-2xl border border-[var(--line)] p-3 text-left hover:border-[var(--teal)]" onClick={() => onReplace(player)}><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{player.displayName}</span><span className="block text-xs text-[var(--muted)]">{playerDetails(player)} · {player.matchesPlayed} games · {waitMinutes(player, serverTime)} waiting</span></span><Plus size={17} className="shrink-0 text-[var(--teal)]" /></button>)}</div></div></div>;
}

function MatchmakerPanel({ sessionId, queue, courts, onChanged }: { sessionId: string; queue: QueueState; courts: Court[]; onChanged: () => void }) {
  const [panelMode, setPanelMode] = useState<"suggested" | "manual">("suggested");
  const [mode, setMode] = useState("BALANCED");
  const [suggestion, setSuggestion] = useState<Suggestion | null>(null);
  const [draft, setDraft] = useState<SuggestionDraft | null>(null);
  const [editing, setEditing] = useState(false);
  const [courtId, setCourtId] = useState("");
  const [manualTeamA, setManualTeamA] = useState<string[]>([]);
  const [manualTeamB, setManualTeamB] = useState<string[]>([]);
  const [pickerTarget, setPickerTarget] = useState<SuggestionPickerTarget | null>(null);
  const [suggestionScope, setSuggestionScope] = useState("");
  const [suggestionCycle, setSuggestionCycle] = useState<{ scope: string; keys: string[] }>({ scope: "", keys: [] });
  const [clock, setClock] = useState(() => Date.now());
  const manualPlayers = queue.waiting;
  const waitingFingerprint = useMemo(() => `${queue.lateArrivalCutoffAt ?? ""}|${queue.waiting.map((player) => `${player.id}:${player.matchesPlayed}:${player.queueEnteredAt ?? ""}:${player.latePenaltyState ?? ""}`).sort().join("|")}`, [queue.lateArrivalCutoffAt, queue.waiting]);
  const cycleScope = `${mode}|${waitingFingerprint}`;
  const excludedSuggestionKeys = suggestionCycle.scope === cycleScope ? suggestionCycle.keys : [];
  const waitingById = useMemo(() => new Map(queue.waiting.map((player) => [player.id, player])), [queue.waiting]);
  const suggestionById = useMemo(() => new Map((suggestion ? [...suggestion.teamA, ...suggestion.teamB] : []).map((player) => [player.id, player])), [suggestion]);
  const getPlayer = (id: string | undefined) => id ? waitingById.get(id) ?? suggestionById.get(id) : undefined;
  const draftIds = draft ? [...draft.teamA, ...draft.teamB] : [];
  const selectedIds = new Set(draftIds);
  const unavailableIds = draftIds.filter((id) => !waitingById.has(id));
  const draftReady = Boolean(draft && draft.teamA.length === 2 && draft.teamB.length === 2 && new Set(draftIds).size === 4 && unavailableIds.length === 0);
  const isAdjusted = Boolean(suggestion && draft && (suggestion.teamA.some((player, index) => draft.teamA[index] !== player.id) || suggestion.teamB.some((player, index) => draft.teamB[index] !== player.id)));
  const expired = Boolean(suggestion && suggestion.expiresAt <= clock);
  const availableCourts = courts.filter((court) => court.status === "AVAILABLE");
  const teamPlayers = (ids: string[]) => ids.map(getPlayer).filter((player): player is SessionPlayer => Boolean(player)).map((player) => player.latePenaltyState ? { ...player, displayName: `${player.displayName} · Late ${pretty(player.latePenaltyState)}` } : player);
  const teamTotal = (ids: string[]) => teamPlayers(ids).reduce((total, player) => total + strengthValue(player), 0);
  const originalDraft: SuggestionDraft | null = suggestion ? { teamA: suggestion.teamA.map((player) => player.id), teamB: suggestion.teamB.map((player) => player.id) } : null;
  useEffect(() => {
    if (!suggestion) return;
    const interval = window.setInterval(() => setClock(Date.now()), 1000);
    return () => window.clearInterval(interval);
  }, [suggestion]);
  const suggest = useMutation({ mutationFn: () => api.suggestions(sessionId, mode, excludedSuggestionKeys), onSuccess: (result) => { if (!result.suggestion) { toast.message(result.noMatch?.message ?? "No valid group is available yet."); return; } const nextSuggestion = result.suggestion; setSuggestion(nextSuggestion); setDraft({ teamA: nextSuggestion.teamA.map((player) => player.id), teamB: nextSuggestion.teamB.map((player) => player.id) }); setSuggestionScope(cycleScope); setEditing(false); setPickerTarget(null); setCourtId(""); setClock(Date.now()); setSuggestionCycle((current) => { const keys = result.cycleRestarted || current.scope !== cycleScope ? [] : current.keys; return { scope: cycleScope, keys: [...new Set([...keys, nextSuggestion.key])].slice(-50) }; }); }, onError: (error) => toast.error(errorMessage(error)) });
  const createSuggested = useMutation({ mutationFn: ({ startNow }: { startNow: boolean }) => { if (!suggestion || !draft || !draftReady) throw new Error("Every selected player must still be waiting."); if (expired) throw new Error("This suggestion expired. Generate a new suggestion or continue in Manual mode."); if (startNow && !courtId) throw new Error("Select an available court first."); return api.createSuggestedMatch(sessionId, { teamA: draft.teamA, teamB: draft.teamB, suggestionToken: suggestion.token, ...(startNow ? { courtId } : {}) }); }, onSuccess: (_match, variables) => { setSuggestion(null); setDraft(null); setSuggestionScope(""); setSuggestionCycle({ scope: "", keys: [] }); setEditing(false); setPickerTarget(null); setCourtId(""); onChanged(); toast.success(variables.startNow ? "Match started." : "Match queued."); } });
  const [manualPickerTeam, setManualPickerTeam] = useState<SuggestionTeam | null>(null);
  const selectedManualIds = useMemo(() => new Set([...manualTeamA, ...manualTeamB]), [manualTeamA, manualTeamB]);
  const manualReady = manualTeamA.length > 0 && manualTeamA.length === manualTeamB.length && [1, 2].includes(manualTeamA.length);
  const manualCreate = useMutation({ mutationFn: ({ startNow }: { startNow: boolean }) => { if (!manualReady) throw new Error("Choose one player per team for singles or two per team for doubles."); if (startNow && !courtId) throw new Error("Select an available court first."); return startNow ? api.startManualMatch(sessionId, manualTeamA, manualTeamB, courtId) : api.queueManualMatch(sessionId, manualTeamA, manualTeamB); }, onSuccess: (_match, variables) => { setManualTeamA([]); setManualTeamB([]); setCourtId(""); onChanged(); toast.success(variables.startNow ? "Match started." : "Match queued."); } });
  const changeMode = (nextMode: string) => { if (nextMode === mode) return; if (isAdjusted && !window.confirm("Discard your edited lineup and generate in the new mode?")) return; setMode(nextMode); setSuggestion(null); setDraft(null); setSuggestionScope(""); setSuggestionCycle({ scope: "", keys: [] }); setEditing(false); setPickerTarget(null); setCourtId(""); };
  const requestSuggestion = () => { if (isAdjusted && !window.confirm("Discard this edited lineup and generate another suggestion?")) return; suggest.mutate(); };
  const resetDraft = () => { if (!originalDraft) return; setDraft({ teamA: [...originalDraft.teamA], teamB: [...originalDraft.teamB] }); setEditing(false); setPickerTarget(null); };
  const replaceSlot = (player: SessionPlayer) => { if (!pickerTarget || !draft) return; setDraft((current) => { if (!current) return current; const next = { teamA: [...current.teamA], teamB: [...current.teamB] }; next[pickerTarget.team === "A" ? "teamA" : "teamB"][pickerTarget.slot] = player.id; return next; }); setPickerTarget(null); };
  const swapSlots = (target: SuggestionPickerTarget) => { if (!pickerTarget || !draft) return; setDraft((current) => { if (!current) return current; const next = { teamA: [...current.teamA], teamB: [...current.teamB] }; const sourceKey = pickerTarget.team === "A" ? "teamA" : "teamB"; const targetKey = target.team === "A" ? "teamA" : "teamB"; const sourceId = next[sourceKey][pickerTarget.slot]; const targetId = next[targetKey][target.slot]; if (!sourceId || !targetId) return current; next[sourceKey][pickerTarget.slot] = targetId; next[targetKey][target.slot] = sourceId; return next; }); setPickerTarget(null); };
  const transferToManual = () => { if (!draft || unavailableIds.length > 0) { toast.error("Replace unavailable players before continuing in Manual mode."); return; } setManualTeamA([...draft.teamA]); setManualTeamB([...draft.teamB]); setPanelMode("manual"); setSuggestion(null); setDraft(null); setEditing(false); setPickerTarget(null); setCourtId(""); };
  const renderSlot = (team: SuggestionTeam, slot: number) => { const id = draft?.[team === "A" ? "teamA" : "teamB"][slot]; const player = id ? getPlayer(id) : undefined; const unavailable = Boolean(id && !waitingById.has(id)); const content = <><span className="min-w-0 flex-1"><span className="block truncate font-semibold">{player?.displayName ?? "Player unavailable"}</span><span className="block truncate text-xs text-[var(--muted)]">{player ? `${playerDetails(player)} · ${player.matchesPlayed} games` : "No longer waiting"}</span></span>{editing && <ChevronDown size={15} className="shrink-0 text-[var(--muted)]" />}</>; return editing ? <button type="button" key={`${team}-${slot}`} className={`focus-ring flex w-full items-center gap-2 rounded-xl border px-3 py-2 text-left ${unavailable ? "border-[#d98964] bg-[#fffaf5]" : "border-[var(--line)] bg-white"}`} onClick={() => setPickerTarget({ team, slot })}>{content}</button> : <div key={`${team}-${slot}`} className={`flex items-center gap-2 rounded-xl border px-3 py-2 ${unavailable ? "border-[#d98964] bg-[#fffaf5]" : "border-[var(--line)] bg-white"}`}>{content}</div>; };
  const showSuggested = Boolean(suggestion && draft);
  return <Card className="h-fit lg:sticky lg:top-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[var(--teal)]">Matchmaker</p><h3 className="display mt-1 text-3xl">Make the next match.</h3></div><Sparkles className="text-[var(--orange)]" size={22} /></div><p className="mt-2 text-sm leading-6 text-[var(--muted)]">Use a fair suggestion or choose a singles/doubles lineup yourself. A saved lineup can wait for a court.</p><div className="mt-5 grid grid-cols-2 rounded-2xl bg-[#f1f5f2] p-1"><button type="button" className={`focus-ring rounded-xl px-3 py-2 text-sm font-semibold ${panelMode === "suggested" ? "bg-white text-[var(--teal-dark)] shadow-sm" : "text-[var(--muted)]"}`} onClick={() => setPanelMode("suggested")}>Suggested</button><button type="button" className={`focus-ring rounded-xl px-3 py-2 text-sm font-semibold ${panelMode === "manual" ? "bg-white text-[var(--teal-dark)] shadow-sm" : "text-[var(--muted)]"}`} onClick={() => setPanelMode("manual")}>Manual</button></div>
    {panelMode === "suggested" ? <><label className="mt-5 block text-sm font-semibold">Match mode<Select value={mode} onChange={(event) => changeMode(event.target.value)}><option value="BALANCED">Balanced</option><option value="MIXED_DOUBLES">Mixed doubles</option><option value="SAME_GENDER">Same gender</option><option value="SAME_SKILL">Same skill</option><option value="OPEN">Open</option></Select></label><Button className="mt-3 w-full" onClick={requestSuggestion} disabled={suggest.isPending || queue.waiting.length < 4}>{suggest.isPending ? "Finding a fair group…" : showSuggested ? "Try another lineup" : "Suggest lineup"}</Button>{queue.waiting.length < 4 && <p className="mt-2 text-xs text-[var(--muted)]">Need four waiting players. There are {queue.waiting.length} ready.</p>}{showSuggested && draft && suggestion && <div className="mt-5 space-y-4 border-t border-[var(--line)] pt-5"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex flex-wrap items-center gap-2"><Badge tone={isAdjusted ? "orange" : "teal"}>{isAdjusted ? "Queue Master adjusted" : "Suggested"}</Badge><span className={`text-xs ${expired ? "text-[#a74646]" : "text-[var(--muted)]"}`}>{remainingSuggestionTime(suggestion.expiresAt, clock)}</span></div><div className="flex gap-2"><Button variant="quiet" className="px-3 py-1.5 text-xs" onClick={() => editing ? setEditing(false) : setEditing(true)}>{editing ? "Done editing" : "Edit lineup"}</Button>{isAdjusted && <Button variant="quiet" className="px-3 py-1.5 text-xs" onClick={resetDraft}>Reset lineup</Button>}</div></div><div className="grid grid-cols-2 gap-2"><div className="rounded-2xl bg-[#edf8f4] p-3"><p className="text-xs font-bold uppercase text-[var(--teal)]">Team A</p><div className="mt-2 space-y-2 text-sm">{[0, 1].map((slot) => renderSlot("A", slot))}</div><p className="mt-2 text-xs text-[var(--muted)]">{teamTotal(draft.teamA)} strength</p></div><div className="rounded-2xl bg-[#fff4ec] p-3"><p className="text-xs font-bold uppercase text-[#a85b2b]">Team B</p><div className="mt-2 space-y-2 text-sm">{[0, 1].map((slot) => renderSlot("B", slot))}</div><p className="mt-2 text-xs text-[var(--muted)]">{teamTotal(draft.teamB)} strength</p></div></div>{isAdjusted ? <p className="rounded-2xl bg-[#fff4ec] px-3 py-2 text-xs leading-5 text-[#8d4824]">This is a Queue Master override. The selected mode’s automatic balance and rotation guarantees may no longer apply.</p> : <p className="text-xs text-[var(--muted)]">{rotationMessage(suggestion)}</p>}{unavailableIds.length > 0 && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">A selected player is no longer waiting. Replace that slot before starting or queueing.</p>}{expired && <div className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]"><p>This suggestion has expired.</p><div className="mt-2 flex flex-wrap gap-2"><Button variant="quiet" className="px-3 py-1.5 text-xs" onClick={requestSuggestion}>Generate fresh suggestion</Button><Button variant="quiet" className="px-3 py-1.5 text-xs" onClick={transferToManual}>Continue in Manual mode</Button></div></div>}<label className="block text-sm font-semibold">Court for immediate start<Select value={courtId} onChange={(event) => setCourtId(event.target.value)}><option value="">No court selected</option>{availableCourts.map((court) => <option value={court.id} key={court.id}>{court.name}</option>)}</Select></label>{availableCourts.length === 0 && <p className="text-xs text-[#8d4824]">No available courts. You can still queue this adjusted matchup.</p>}{availableCourts.length > 0 && !courtId && <p className="text-xs text-[var(--muted)]">Choose an available court above to enable Start match.</p>}{createSuggested.isError && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(createSuggested.error)}</p>}<div className="flex flex-col gap-2 sm:flex-row"><Button className="flex-1" onClick={() => createSuggested.mutate({ startNow: true })} disabled={!draftReady || expired || !courtId || createSuggested.isPending}>{createSuggested.isPending ? "Starting…" : "Start match"}</Button><Button variant="quiet" className="flex-1" onClick={() => createSuggested.mutate({ startNow: false })} disabled={!draftReady || expired || createSuggested.isPending}>{createSuggested.isPending ? "Saving…" : "Queue matchup"}</Button></div></div>}</> : <div className="mt-5 space-y-4 border-t border-[var(--line)] pt-5"><div className="grid grid-cols-2 gap-2"><div className="rounded-2xl border border-[var(--line)] bg-[#edf8f4] p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold uppercase text-[var(--teal)]">Team A</p><Badge tone="teal">{manualTeamA.length}/2</Badge></div><div className="mt-3 space-y-2">{teamPlayers(manualTeamA).map((player) => <div key={player.id} className="flex items-center gap-1 rounded-xl bg-white px-2 py-2 text-sm"><span className="min-w-0 flex-1 truncate">{player.displayName}</span><button type="button" className="focus-ring rounded-full p-1 text-[var(--muted)] hover:text-[#a74646]" aria-label={`Remove ${player.displayName} from Team A`} onClick={() => setManualTeamA((current) => current.filter((playerId) => playerId !== player.id))}><X size={14} /></button></div>)}{manualTeamA.length < 2 && <Button variant="quiet" className="w-full px-2 py-1.5 text-xs" onClick={() => setManualPickerTeam("A")}><Plus size={14} /> Add player</Button>}</div></div><div className="rounded-2xl border border-[var(--line)] bg-[#fff4ec] p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold uppercase text-[#a85b2b]">Team B</p><Badge tone="orange">{manualTeamB.length}/2</Badge></div><div className="mt-3 space-y-2">{teamPlayers(manualTeamB).map((player) => <div key={player.id} className="flex items-center gap-1 rounded-xl bg-white px-2 py-2 text-sm"><span className="min-w-0 flex-1 truncate">{player.displayName}</span><button type="button" className="focus-ring rounded-full p-1 text-[var(--muted)] hover:text-[#a74646]" aria-label={`Remove ${player.displayName} from Team B`} onClick={() => setManualTeamB((current) => current.filter((playerId) => playerId !== player.id))}><X size={14} /></button></div>)}{manualTeamB.length < 2 && <Button variant="quiet" className="w-full px-2 py-1.5 text-xs" onClick={() => setManualPickerTeam("B")}><Plus size={14} /> Add player</Button>}</div></div></div><p className="text-xs text-[var(--muted)]">Choose one player per team for singles, or two per team for doubles.</p><label className="block text-sm font-semibold">Court for immediate start<Select value={courtId} onChange={(event) => setCourtId(event.target.value)}><option value="">No court selected</option>{availableCourts.map((court) => <option value={court.id} key={court.id}>{court.name}</option>)}</Select></label>{availableCourts.length === 0 && <p className="text-xs text-[#8d4824]">No available courts. You can still queue this matchup.</p>}{manualCreate.isError && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(manualCreate.error)}</p>}<div className="flex flex-col gap-2"><Button onClick={() => manualCreate.mutate({ startNow: true })} disabled={!manualReady || !courtId || manualCreate.isPending}>{manualCreate.isPending ? "Starting…" : "Start match"}</Button><Button variant="quiet" onClick={() => manualCreate.mutate({ startNow: false })} disabled={!manualReady || manualCreate.isPending}>Queue matchup</Button></div></div>}
    {manualPickerTeam && <ManualPlayerPicker team={manualPickerTeam} players={manualPlayers} selectedIds={selectedManualIds} onSelect={(player) => { if (manualPickerTeam === "A") setManualTeamA((current) => [...current, player.id]); else setManualTeamB((current) => [...current, player.id]); setManualPickerTeam(null); }} onClose={() => setManualPickerTeam(null)} />}
    {pickerTarget && draft && suggestion && <SuggestedPlayerPicker target={pickerTarget} currentPlayer={getPlayer(draft[pickerTarget.team === "A" ? "teamA" : "teamB"][pickerTarget.slot])} opponents={(pickerTarget.team === "A" ? draft.teamB : draft.teamA).map((id, slot) => ({ player: getPlayer(id), target: { team: pickerTarget.team === "A" ? "B" : "A", slot } }))} players={manualPlayers} selectedIds={selectedIds} serverTime={queue.serverTime} onReplace={replaceSlot} onSwap={swapSlots} onClose={() => setPickerTarget(null)} />}
  </Card>;
}

function QueueView({ sessionId }: { sessionId: string }) {
  const queryClient = useQueryClient();
  const [filter, setFilter] = useState<QueueFilter>("WAITING");
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const queueQuery = useQuery({ queryKey: ["queue", sessionId], queryFn: () => api.queue(sessionId), refetchInterval: 8000 });
  const courtsQuery = useQuery({ queryKey: ["courts", sessionId], queryFn: () => api.courts(sessionId), refetchInterval: 8000 });
  const queue = queueQuery.data;
  const allPlayers = useMemo(() => { if (!queue) return []; return [...queue.waiting, ...queue.resting, ...queue.inactive, ...queue.queued, ...queue.playing]; }, [queue]);
  const filtered = useMemo(() => { const needle = search.trim().toLowerCase(); return allPlayers.filter((player) => (filter === "ALL" || (filter === "INACTIVE" ? ["INACTIVE", "CHECKED_OUT"].includes(player.status) : player.status === filter)) && (!needle || player.displayName.toLowerCase().includes(needle))); }, [allPlayers, filter, search]);
  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const visible = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
  const invalidate = () => { queryClient.invalidateQueries({ queryKey: ["queue", sessionId] }); queryClient.invalidateQueries({ queryKey: ["courts", sessionId] }); queryClient.invalidateQueries({ queryKey: ["matches", sessionId] }); };
  const counts: Record<Exclude<QueueFilter, "ALL">, number> = queue ? { WAITING: queue.waiting.length, RESTING: queue.resting.length, INACTIVE: queue.inactive.length, QUEUED: queue.queued.length, PLAYING: queue.playing.length } : { WAITING: 0, RESTING: 0, INACTIVE: 0, QUEUED: 0, PLAYING: 0 };
  const labels: { key: QueueFilter; label: string }[] = [{ key: "WAITING", label: "Waiting" }, { key: "RESTING", label: "Resting" }, { key: "INACTIVE", label: "Not checked in" }, { key: "QUEUED", label: "Queued" }, { key: "PLAYING", label: "Playing" }];
  const changeFilter = (next: QueueFilter) => { setPage(1); setFilter(next); };
  const changeSearch = (next: string) => { setPage(1); setSearch(next); };
  return <div className="space-y-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm text-[var(--muted)]">Queue operations</p><h2 className="display text-4xl">Build the next matchup.</h2></div><div className="flex items-center gap-2 text-sm text-[var(--muted)]"><UsersRound size={17} className="text-[var(--teal)]" /> {allPlayers.length} rostered players</div></div><div className="flex gap-2 overflow-x-auto pb-1">{labels.map(({ key, label }) => <button key={key} className={`focus-ring shrink-0 rounded-full border px-3 py-2 text-xs font-semibold transition ${filter === key ? "border-[var(--teal)] bg-[var(--teal)] text-white" : "border-[var(--line)] bg-white text-[var(--muted)] hover:border-[var(--teal)]"}`} onClick={() => changeFilter(key)}>{label} <span className="ml-1 opacity-75">{counts[key as Exclude<QueueFilter, "ALL">]}</span></button>)}</div>{queueQuery.error && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">{errorMessage(queueQuery.error)}</p>}<div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_360px]"><div className="min-w-0"><Card className="p-0"><div className="flex flex-col gap-3 border-b border-[var(--line)] p-4 sm:flex-row"><label className="relative block flex-1"><Search size={16} className="absolute left-3 top-3 text-[var(--muted)]" /><Input className="pl-9" value={search} onChange={(event) => changeSearch(event.target.value)} placeholder="Search players" aria-label="Search players" /></label><div className="flex items-center gap-2 text-xs text-[var(--muted)]"><Filter size={15} /> {filtered.length} shown</div></div><div className="hidden grid-cols-[minmax(140px,1.4fr)_70px_112px_56px_56px_92px_auto] gap-3 border-b border-[var(--line)] bg-[#fbfdfb] px-3 py-3 text-xs font-bold uppercase tracking-[0.12em] text-[var(--muted)] md:grid"><span>Player</span><span>Skill</span><span>Games</span><span>Wait</span><span>Status</span><span>Record</span><span>Action</span></div>{queueQuery.isPending ? <div className="space-y-2 p-4"><div className="h-12 animate-pulse rounded-2xl bg-[#f1f5f2]" /><div className="h-12 animate-pulse rounded-2xl bg-[#f1f5f2]" /></div> : visible.length === 0 ? <div className="p-4"><EmptyState icon={UsersRound} title="No players here" body={search ? "Try a different search or clear the filter." : "Players will appear as they check in."} /></div> : <div>{visible.map((player) => <PlayerQueueRow key={player.id} player={player} sessionId={sessionId} onChanged={invalidate} />)}</div>}<div className="flex items-center justify-between border-t border-[var(--line)] px-4 py-3"><p className="text-xs text-[var(--muted)]">Page {Math.min(page, pageCount)} of {pageCount} · 15 per page</p><div className="flex gap-2"><Button variant="quiet" className="px-3" aria-label="Previous page" disabled={page <= 1} onClick={() => setPage((current) => Math.max(1, current - 1))}><ArrowLeft size={15} /></Button><Button variant="quiet" className="px-3" aria-label="Next page" disabled={page >= pageCount} onClick={() => setPage((current) => Math.min(pageCount, current + 1))}><ArrowRight size={15} /></Button></div></div></Card></div><MatchmakerPanel key={sessionId} sessionId={sessionId} queue={queue ?? { waiting: [], resting: [], inactive: [], queued: [], playing: [], serverTime: new Date().toISOString() }} courts={courtsQuery.data ?? []} onChanged={invalidate} /></div></div>;
}

function PlayersView({ sessionId }: { sessionId: string }) {
  const queryClient = useQueryClient();
  const [selected, setSelected] = useState<string[]>([]);
  const [deleteMode, setDeleteMode] = useState(false);
  const [deleteSelected, setDeleteSelected] = useState<string[]>([]);
  const [deletePreview, setDeletePreview] = useState<PlayerDeletionPreview | null>(null);
  const [name, setName] = useState("");
  const [gender, setGender] = useState<"MALE" | "FEMALE">("MALE");
  const [skill, setSkill] = useState("NEWBIE");
  const playersQuery = useQuery({ queryKey: ["players"], queryFn: api.players });
  const sessionPlayersQuery = useQuery({ queryKey: ["sessionPlayers", sessionId], queryFn: () => api.sessionPlayers(sessionId) });
  const add = useMutation({ mutationFn: () => api.addPlayers(sessionId, selected), onSuccess: () => { setSelected([]); queryClient.invalidateQueries({ queryKey: ["sessionPlayers", sessionId] }); queryClient.invalidateQueries({ queryKey: ["queue", sessionId] }); queryClient.invalidateQueries({ queryKey: ["sessions"] }); toast.success("Players added to the session."); } });
  const create = useMutation({ mutationFn: () => api.createPlayer({ displayName: name.trim(), gender, skillLevel: skill }), onSuccess: (player) => { setName(""); queryClient.setQueryData<Player[]>(["players"], (current = []) => [...current, player].sort((a, b) => a.displayName.localeCompare(b.displayName))); toast.success("Player created."); } });
  const preview = useMutation({ mutationFn: (playerIds: string[]) => api.playerDeletionPreview(playerIds), onSuccess: setDeletePreview });
  const remove = useMutation({ mutationFn: (playerIds: string[]) => api.deletePlayers(playerIds), onSuccess: (result) => { setDeleteSelected([]); setDeletePreview(null); setDeleteMode(false); setSelected([]); queryClient.invalidateQueries({ queryKey: ["players"] }); queryClient.invalidateQueries({ queryKey: ["sessions"] }); for (const affectedSessionId of result.affectedSessionIds) { queryClient.invalidateQueries({ queryKey: ["sessionPlayers", affectedSessionId] }); queryClient.invalidateQueries({ queryKey: ["queue", affectedSessionId] }); queryClient.invalidateQueries({ queryKey: ["courts", affectedSessionId] }); queryClient.invalidateQueries({ queryKey: ["matches", affectedSessionId] }); queryClient.invalidateQueries({ queryKey: ["history", affectedSessionId] }); queryClient.invalidateQueries({ queryKey: ["rankings", affectedSessionId] }); queryClient.invalidateQueries({ queryKey: ["fees", affectedSessionId] }); queryClient.invalidateQueries({ queryKey: ["payments", affectedSessionId] }); } queryClient.invalidateQueries({ queryKey: ["rankings", "career"] }); toast.success(`${result.deletedPlayerIds.length} player${result.deletedPlayerIds.length === 1 ? "" : "s"} deleted.`); } });
  const players = playersQuery.data ?? [];
  const addedIds = useMemo(() => new Set((sessionPlayersQuery.data ?? []).map((player) => player.playerId).filter((id): id is string => Boolean(id))), [sessionPlayersQuery.data]);
  const rosterReady = sessionPlayersQuery.isSuccess;
  const requestDelete = (playerIds: string[]) => { if (!playerIds.length) return; setDeleteSelected(playerIds); preview.mutate(playerIds); };
  const previewBody = deletePreview?.busyPlayers.length
    ? `Deletion is blocked because ${deletePreview.busyPlayers.map((player) => `${player.displayName} is ${pretty(player.status).toLowerCase()}`).join(", ")}. Finish or discard those matches first.`
    : `This permanently deletes ${deletePreview?.playerNames.join(", ") ?? "the selected players"}, their roster entries, complete matches, scores, payments, history, and statistics. ${deletePreview?.affectedSessionIds.length ?? 0} session(s) and ${deletePreview?.affectedMatchIds.length ?? 0} match(es) are affected; other participants' derived statistics will be rebuilt.`;
  return <div className="space-y-5"><div><p className="text-sm text-[var(--muted)]">Roster</p><h2 className="display text-4xl">Players and check-in.</h2></div><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_360px]"><Card><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold">Player directory</h3><p className="mt-1 text-sm text-[var(--muted)]">{deleteMode ? "Choose profiles for permanent account-wide deletion." : "Players already added to this session cannot be selected again."}</p></div><div className="flex items-center gap-2">{deleteMode ? <><Button variant="quiet" className="px-3 py-1.5 text-xs" onClick={() => setDeleteSelected(players.map((player) => player.id))}>Select all visible</Button><Button variant="quiet" className="px-3 py-1.5 text-xs" onClick={() => setDeleteSelected([])}>Clear</Button><Button variant="quiet" className="px-3 py-1.5 text-xs" onClick={() => { setDeleteMode(false); setDeleteSelected([]); }}>Cancel</Button></> : <Button variant="quiet" className="px-3 py-1.5 text-xs" onClick={() => setDeleteMode(true)}><Trash2 size={14} /> Delete players</Button>}<Badge tone={deleteMode ? "orange" : "teal"}>{deleteMode ? `${deleteSelected.length} to delete` : `${selected.length} selected`}</Badge></div></div><div className="mt-4 max-h-[520px] space-y-2 overflow-y-auto pr-1">{players.map((player) => { const added = addedIds.has(player.id); const checked = selected.includes(player.id); const deleting = deleteSelected.includes(player.id); const unavailable = added || !rosterReady; if (deleteMode) return <div key={player.id} className={`flex items-center gap-3 rounded-2xl border border-[var(--line)] p-3 ${deleting ? "border-[#d98964] bg-[#fffaf5]" : "hover:border-[var(--teal)]"}`}><input type="checkbox" aria-label={`Select ${player.displayName} for deletion`} checked={deleting} onChange={(event) => setDeleteSelected((current) => event.target.checked ? [...current, player.id] : current.filter((id) => id !== player.id))} /><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{player.displayName}</span><span className="text-xs text-[var(--muted)]">{player.gender === "MALE" ? "Male" : "Female"} · {pretty(player.skillLevel)}{added ? " · Added to session" : ""}</span></span><Badge tone={deleting ? "orange" : "teal"}>{deleting ? "Selected" : "Available"}</Badge></div>; return <div key={player.id} className={`flex items-center gap-3 rounded-2xl border border-[var(--line)] p-3 ${unavailable ? "bg-[#f7faf8] opacity-65" : "hover:border-[var(--teal)]"}`}><label className={`flex min-w-0 flex-1 items-center gap-3 ${unavailable ? "cursor-not-allowed" : "cursor-pointer"}`}><input type="checkbox" checked={checked || added} disabled={unavailable || add.isPending} onChange={(event) => setSelected((current) => event.target.checked ? [...current, player.id] : current.filter((id) => id !== player.id))} /><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{player.displayName}</span><span className="text-xs text-[var(--muted)]">{player.gender === "MALE" ? "Male" : "Female"} · {pretty(player.skillLevel)}</span></span>{!rosterReady ? <Badge tone="gray">Checking…</Badge> : added ? <Badge tone="gray">Added to session</Badge> : checked ? <Badge tone="orange">Selected</Badge> : <Badge tone="teal">Available</Badge>}</label><Button variant="quiet" className="shrink-0 px-2 py-1.5" aria-label={`Delete ${player.displayName}`} title={`Delete ${player.displayName}`} onClick={() => requestDelete([player.id])}><Trash2 size={15} /></Button></div>; })}</div>{(playersQuery.error || sessionPlayersQuery.error || preview.isError) && <p role="alert" className="mt-3 rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(playersQuery.error ?? sessionPlayersQuery.error ?? preview.error)}</p>}<Button className="mt-4 w-full" disabled={!selected.length || !rosterReady || add.isPending} onClick={() => add.mutate()}>{add.isPending ? "Adding…" : "Add selected to session"}</Button>{deleteMode && <Button variant="danger" className="mt-2 w-full" disabled={!deleteSelected.length || preview.isPending || remove.isPending} onClick={() => requestDelete(deleteSelected)}>{preview.isPending ? "Checking impact…" : `Delete ${deleteSelected.length || "selected"} player${deleteSelected.length === 1 ? "" : "s"}`}</Button>}{add.isError && <p className="mt-2 text-sm text-[#8d4824]">{errorMessage(add.error)}</p>}</Card><Card><div className="flex items-center gap-2"><Plus size={17} className="text-[var(--teal)]" /><h3 className="font-semibold">Create player</h3></div><form className="mt-4 space-y-3" onSubmit={(event) => { event.preventDefault(); create.mutate(); }}><label className="block text-sm font-semibold">Display name<Input value={name} onChange={(event) => setName(event.target.value)} required /></label><label className="block text-sm font-semibold">Gender<Select value={gender} onChange={(event) => setGender(event.target.value as "MALE" | "FEMALE")}><option value="MALE">Male</option><option value="FEMALE">Female</option></Select></label><label className="block text-sm font-semibold">Skill level<Select value={skill} onChange={(event) => setSkill(event.target.value)}>{SKILLS.map((option) => <option key={option} value={option}>{pretty(option)}</option>)}</Select></label><Button className="w-full" disabled={create.isPending}>{create.isPending ? "Creating…" : "Create player"}</Button></form>{create.isError && <p className="mt-2 text-sm text-[#8d4824]">{errorMessage(create.error)}</p>}</Card></div>{deletePreview && <DestructiveConfirmDialog title="Permanently delete players?" body={previewBody} confirmLabel="Delete permanently" pending={remove.isPending} error={remove.isError ? remove.error : undefined} onConfirm={() => { if (!deletePreview.busyPlayers.length) remove.mutate(deletePreview.playerIds); }} onClose={() => { if (!remove.isPending) setDeletePreview(null); }} />}</div>;
}

function OfflineSyncPanel({ accountId: providedAccountId }: { accountId: string | undefined }) {
  const [accountId, setAccountId] = useState(providedAccountId ?? "");
  const [meta, setMeta] = useState<Awaited<ReturnType<typeof getMeta>>>(undefined);
  const [online, setOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);
  const [storage, setStorage] = useState<Awaited<ReturnType<typeof storageEstimate>>>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [confirm, setConfirm] = useState<"force" | "remove" | "download" | null>(null);
  const refresh = useCallback(async () => { if (!accountId) return; setMeta(await getMeta(accountId)); setStorage(await storageEstimate()); }, [accountId]);
  useEffect(() => { void (async () => { const profile = providedAccountId ? null : await retainedProfile(); if (profile) setAccountId(profile.accountId); })(); const onStatus = () => { setOnline(navigator.onLine); void refresh(); }; window.addEventListener("online", onStatus); window.addEventListener("offline", onStatus); window.addEventListener("shuttle-queue-offline-change", onStatus); return () => { window.removeEventListener("online", onStatus); window.removeEventListener("offline", onStatus); window.removeEventListener("shuttle-queue-offline-change", onStatus); }; }, [providedAccountId, refresh]);
  const runSync = async (force = false) => { if (!accountId) return; setBusy(true); setError(null); try { const result = await syncAccount(accountId, force); if (result.state === "conflict") setConfirm("force"); else toast.success(result.state === "uploaded" ? "Pending changes uploaded." : "Local copy is up to date."); await refresh(); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } };
  const download = async () => { if (!accountId) return; setBusy(true); setError(null); try { await downloadFromCloud(accountId, false); toast.success("Downloaded the cloud copy."); await refresh(); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } };
  const remove = async () => { if (!accountId) return; setBusy(true); try { await clearAccountData(accountId); setConfirm(null); window.location.reload(); } catch (reason) { setError(errorMessage(reason)); setBusy(false); } };
  const used = storage?.usage ? `${Math.round(storage.usage / 1024 / 1024)} MB` : "—"; const quota = storage?.quota ? `${Math.round(storage.quota / 1024 / 1024)} MB` : "—";
  return <Card><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[var(--teal)]">Device storage</p><h3 className="display mt-1 text-3xl">Offline workspace</h3></div><Badge tone={online ? "teal" : "orange"}>{online ? "Online" : "Offline"}</Badge></div><p className="mt-3 text-sm leading-6 text-[var(--muted)]">All current queue operations are stored on this device first. Anyone with access to this browser profile can open the downloaded account.</p><div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-[#f7faf8] p-3"><p className="text-xs text-[var(--muted)]">Local status</p><p className="mt-1 font-semibold">{meta?.dirty ? "Pending changes" : "Up to date"}</p></div><div className="rounded-2xl bg-[#f7faf8] p-3"><p className="text-xs text-[var(--muted)]">Cloud revision</p><p className="mt-1 font-semibold">{meta?.baseCloudRevision ?? "—"}</p></div><div className="rounded-2xl bg-[#f7faf8] p-3"><p className="text-xs text-[var(--muted)]">Storage</p><p className="mt-1 font-semibold">{used} / {quota}</p></div></div>{meta?.lastSyncAt && <p className="mt-3 text-xs text-[var(--muted)]">Last sync {new Date(meta.lastSyncAt).toLocaleString()}</p>}{error && <p role="alert" className="mt-4 rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{error}</p>}<div className="mt-5 flex flex-col gap-2 sm:flex-row"><Button disabled={!online || busy} onClick={() => void runSync()}><RefreshCw size={15} /> {busy ? "Syncing…" : "Sync now"}</Button><Button variant="quiet" disabled={!online || busy} onClick={() => meta?.dirty ? setConfirm("download") : void download()}>Download from cloud</Button><Button variant="quiet" disabled={busy} onClick={() => setConfirm("remove")}>Remove downloaded data</Button></div>{confirm === "force" && <DestructiveConfirmDialog title="Replace cloud data?" body="This device has pending changes and the cloud changed too. Forcing sync makes this complete local snapshot the account copy and removes newer cloud work from other devices." confirmLabel="Replace cloud" pending={busy} onConfirm={() => { setConfirm(null); void runSync(true); }} onClose={() => setConfirm(null)} />}{confirm === "download" && <DestructiveConfirmDialog title="Download and discard local changes?" body="This device has pending work. Downloading now will permanently discard those local changes. You can sync this device first, or cancel." confirmLabel="Discard and download" secondaryLabel="Sync this device first" pending={busy} onSecondary={() => { setConfirm(null); void runSync(); }} onConfirm={() => { setConfirm(null); setBusy(true); void downloadFromCloud(accountId, true).then(() => refresh()).catch((reason) => setError(errorMessage(reason))).finally(() => setBusy(false)); }} onClose={() => setConfirm(null)} />}{confirm === "remove" && <DestructiveConfirmDialog title="Remove downloaded data?" body="This deletes this account’s offline copy and any pending work from this browser. The installed app remains, and the cloud account is unchanged." confirmLabel="Remove local data" pending={busy} onConfirm={() => void remove()} onClose={() => setConfirm(null)} />}</Card>;
}

function dateTimeInputForTimezone(value: string | null | undefined, timeZone: string) {
  if (!value) return "";
  const parts = new Intl.DateTimeFormat("en-US", { timeZone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(new Date(value));
  const result = Object.fromEntries(parts.filter((part) => part.type !== "literal").map((part) => [part.type, part.value]));
  return `${result.year}-${result.month}-${result.day}T${result.hour}:${result.minute}`;
}

function currentClockForTimezone(timeZone: string) {
  const parts = new Intl.DateTimeFormat("en-US", { timeZone, hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(new Date());
  const result = Object.fromEntries(parts.filter((part) => part.type !== "literal").map((part) => [part.type, part.value]));
  return `${result.hour}:${result.minute}`;
}

function LateArrivalSettingsCard({ session, sessionId }: { session: SessionSummary; sessionId: string }) {
  const queryClient = useQueryClient();
  const settingsQuery = useQuery({ queryKey: ["settings"], queryFn: api.settings });
  const settings = settingsQuery.data;
  const [defaultTimeOverride, setDefaultTimeOverride] = useState<string | undefined>(undefined);
  const [customDateTimeOverride, setCustomDateTimeOverride] = useState<string | undefined>(undefined);
  const defaultTime = defaultTimeOverride ?? settings?.defaultLateArrivalCutoffTime ?? "";
  const customDateTime = customDateTimeOverride ?? dateTimeInputForTimezone(session.lateArrivalCutoffAt, settings?.timeZone ?? "Asia/Manila");
  const refresh = () => { queryClient.invalidateQueries({ queryKey: ["settings"] }); queryClient.invalidateQueries({ queryKey: ["sessions"] }); queryClient.invalidateQueries({ queryKey: ["queue", sessionId] }); };
  const saveDefault = useMutation({ mutationFn: (value: string | null) => api.updateSettings({ defaultLateArrivalCutoffTime: value }, settings?.version), onSuccess: (_result, value) => { setDefaultTimeOverride(value ?? ""); refresh(); toast.success(value ? "Account default saved." : "Account default cleared."); } });
  const updatePolicy = useMutation({ mutationFn: (body: { mode: "SET_NOW" | "APPLY_ACCOUNT_DEFAULT" | "DISABLED" | "SET_CUSTOM"; localDateTime?: string }) => api.updateLateArrivalPolicy(sessionId, body, session.version), onSuccess: () => { refresh(); toast.success("Current queue late-arrival policy updated."); } });
  const disabled = false;
  const cutoffLabel = session.lateArrivalCutoffAt ? new Date(session.lateArrivalCutoffAt).toLocaleString(undefined, { timeZone: settings?.timeZone ?? "Asia/Manila" }) : "Disabled";
  return <Card><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[var(--teal)]">Arrival policy</p><h3 className="display mt-1 text-3xl">Late check-in rules.</h3></div><Badge tone={session.lateArrivalCutoffAt ? "orange" : "gray"}>{session.lateArrivalCutoffAt ? "Enabled" : "Disabled"}</Badge></div><p className="mt-3 text-sm leading-6 text-[var(--muted)]">A first check-in after the cutoff receives one pending penalty. Suggested lineups prefer on-time players, while manual lineups remain allowed. Changes apply to future check-ins only.</p><div className="mt-5 grid gap-5 lg:grid-cols-2"><div className="rounded-2xl bg-[#f7faf8] p-4"><h4 className="font-semibold">Account default preset</h4><p className="mt-1 text-xs leading-5 text-[var(--muted)]">Reusable only; it is never applied automatically. Account timezone: {settings?.timeZone ?? "Asia/Manila"}.</p><label className="mt-3 block text-sm font-semibold">Default arrival cutoff<Input type="time" value={defaultTime} onChange={(event) => setDefaultTimeOverride(event.target.value)} /></label><div className="mt-3 flex flex-wrap gap-2"><Button onClick={() => saveDefault.mutate(defaultTime || null)} disabled={saveDefault.isPending || settingsQuery.isPending}>{saveDefault.isPending ? "Saving…" : "Save default"}</Button><Button variant="quiet" onClick={() => saveDefault.mutate(null)} disabled={saveDefault.isPending}>Clear</Button><Button variant="quiet" onClick={() => setDefaultTimeOverride(currentClockForTimezone(settings?.timeZone ?? "Asia/Manila"))} disabled={saveDefault.isPending}>Use current time</Button></div>{saveDefault.isError && <p role="alert" className="mt-2 text-xs text-[#8d4824]">{errorMessage(saveDefault.error)}</p>}</div><div className="rounded-2xl bg-[#fffaf5] p-4"><h4 className="font-semibold">This session</h4><p className="mt-1 text-xs leading-5 text-[var(--muted)]">Current cutoff: <span className="font-semibold text-[var(--ink)]">{cutoffLabel}</span> ({settings?.timeZone ?? "Asia/Manila"})</p><div className="mt-3 flex flex-wrap gap-2"><Button variant="quiet" onClick={() => updatePolicy.mutate({ mode: "APPLY_ACCOUNT_DEFAULT" })} disabled={disabled || !settings?.defaultLateArrivalCutoffTime || updatePolicy.isPending}>Apply account default</Button><Button variant="quiet" onClick={() => updatePolicy.mutate({ mode: "SET_NOW" })} disabled={disabled || updatePolicy.isPending}>Set to now</Button><Button variant="quiet" onClick={() => updatePolicy.mutate({ mode: "DISABLED" })} disabled={disabled || updatePolicy.isPending}>Disable</Button></div><label className="mt-3 block text-sm font-semibold">Custom cutoff ({settings?.timeZone ?? "Asia/Manila"})<Input type="datetime-local" value={customDateTime} onChange={(event) => setCustomDateTimeOverride(event.target.value)} disabled={disabled} /></label><Button className="mt-3 w-full" onClick={() => updatePolicy.mutate({ mode: "SET_CUSTOM", localDateTime: customDateTime })} disabled={disabled || !customDateTime || updatePolicy.isPending}>{updatePolicy.isPending ? "Updating…" : "Save custom cutoff"}</Button>{disabled && <p className="mt-2 text-xs text-[var(--muted)]">Ended or cancelled sessions cannot change arrival rules.</p>}{updatePolicy.isError && <p role="alert" className="mt-2 text-xs text-[#8d4824]">{errorMessage(updatePolicy.error)}</p>}</div></div></Card>;
}

function SessionSettingsControls({ session, sessionId, accountId, onReset, onDeleted }: { session: SessionSummary; sessionId: string; accountId?: string; onReset: (session: SessionSummary) => void; onDeleted: () => void }) {
  const queryClient = useQueryClient();
  const [confirmAction, setConfirmAction] = useState<"reset" | "delete" | null>(null);
  const [disposition, setDisposition] = useState<"KEEP" | "DELETE_ALL">("KEEP");
  const [deletionPreview, setDeletionPreview] = useState<PlayerDeletionPreview | null>(null);
  const sessionPlayersQuery = useQuery({ queryKey: ["sessionPlayers", sessionId], queryFn: () => api.sessionPlayers(sessionId) });
  const reset = useMutation({ mutationFn: () => api.resetSession(sessionId, session.version), onSuccess: (updated) => { setConfirmAction(null); onReset(updated); toast.success("Session reset to a fresh draft."); } });
  const preview = useMutation({ mutationFn: (playerIds: string[]) => api.playerDeletionPreview(playerIds), onSuccess: setDeletionPreview });
  const remove = useMutation({ mutationFn: () => api.deleteSession(sessionId, session.version, disposition), onSuccess: () => { setConfirmAction(null); setDeletionPreview(null); queryClient.invalidateQueries({ queryKey: ["players"] }); onDeleted(); toast.success("Session deleted."); } });
  const pending = reset.isPending || remove.isPending || preview.isPending;
  const openDelete = () => { setDeletionPreview(disposition === "KEEP" ? null : deletionPreview); setConfirmAction("delete"); };
  const changeDisposition = (next: "KEEP" | "DELETE_ALL") => { setDisposition(next); setDeletionPreview(null); if (next === "DELETE_ALL") { const ids = (sessionPlayersQuery.data ?? []).map((player) => player.playerId).filter((id): id is string => Boolean(id)); if (ids.length) preview.mutate(ids); else setDeletionPreview({ playerIds: [], playerNames: [], busyPlayers: [], affectedSessionIds: [], affectedMatchIds: [], affectedPaymentIds: [], otherParticipantPlayerIds: [], otherParticipantSessionPlayerIds: [] }); } };
  const confirm = () => { if (confirmAction === "reset") reset.mutate(); else if (confirmAction === "delete" && (disposition === "KEEP" || (deletionPreview && !deletionPreview.busyPlayers.length))) remove.mutate(); else if (confirmAction === "delete") toast.error(deletionPreview?.busyPlayers.length ? "Busy rostered players must finish or be discarded before deletion." : "The deletion impact is still loading."); };
  const deleteBody = disposition === "KEEP"
    ? `The ${session.name} session, roster entries, courts, payments, and all related history will be permanently deleted. Global player profiles will be kept for other sessions.`
    : deletionPreview
      ? `This removes the ${session.name} session and permanently deletes ${deletionPreview.playerNames.join(", ") || "all rostered player profiles"} across the account. ${deletionPreview.affectedMatchIds.length} match(es) and ${deletionPreview.affectedPaymentIds.length} payment(s) will be removed; other participants’ derived statistics will be rebuilt.`
      : "Loading the account-wide impact of deleting every rostered player…";
  return <div className="space-y-5"><div><p className="text-sm text-[var(--muted)]">Session settings</p><h2 className="display text-4xl">Keep the day tidy.</h2></div><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_380px]"><Card><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[var(--teal)]">{session.name}</p><h3 className="display mt-1 text-3xl">Session overview</h3></div><StatusBadge status={session.status} /></div><div className="mt-6 grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-[#f7faf8] p-4"><p className="text-xs uppercase tracking-[0.12em] text-[var(--muted)]">Scoring</p><p className="mt-2 font-semibold">Race to {session.scoring.pointsToWin}</p><p className="mt-1 text-sm text-[var(--muted)]">Win by {session.scoring.winBy} · cap {session.scoring.scoreCap ?? "none"} · best of {session.scoring.bestOf}</p></div><div className="rounded-2xl bg-[#f7faf8] p-4"><p className="text-xs uppercase tracking-[0.12em] text-[var(--muted)]">Setup</p><p className="mt-2 font-semibold">{session.playerCount ?? 0} rostered players</p><p className="mt-1 text-sm text-[var(--muted)]">{session.courtCount ?? 0} courts configured</p></div></div><p className="mt-5 text-sm leading-6 text-[var(--muted)]">Resetting keeps this session’s name, roster, courts, and scoring rules, but removes gameplay activity so you can run it again from a clean draft.</p></Card><Card className="border-[#f1c5b5]"><div className="flex items-start gap-3"><div className="grid size-10 place-items-center rounded-2xl bg-[#fff0e4] text-[#a74646]"><Settings2 size={19} /></div><div><h3 className="font-semibold">Danger zone</h3><p className="mt-1 text-sm leading-6 text-[var(--muted)]">These actions permanently change this session. A confirmation dialog appears before anything is sent.</p></div></div><div className="mt-6 space-y-3"><div className="rounded-2xl border border-[var(--line)] p-4"><div className="flex items-start gap-3"><RotateCcw className="mt-0.5 shrink-0 text-[var(--orange)]" size={18} /><div className="min-w-0 flex-1"><p className="font-semibold">Reset current session</p><p className="mt-1 text-xs leading-5 text-[var(--muted)]">Delete matches, scores, payments, and session stats. Keep the roster and setup.</p><Button variant="quiet" className="mt-3 w-full" disabled={pending} onClick={() => setConfirmAction("reset")}>Reset to draft</Button></div></div></div><div className="rounded-2xl border border-[#f1c5b5] bg-[#fffaf7] p-4"><div className="flex items-start gap-3"><Trash2 className="mt-0.5 shrink-0 text-[#a74646]" size={18} /><div className="min-w-0 flex-1"><p className="font-semibold">Delete this session</p><p className="mt-1 text-xs leading-5 text-[var(--muted)]">Choose whether global player profiles should remain reusable after this session is removed.</p><label className="mt-3 block text-sm font-semibold">Player profiles after deletion<Select value={disposition} onChange={(event) => changeDisposition(event.target.value as "KEEP" | "DELETE_ALL")}><option value="KEEP">Keep player profiles</option><option value="DELETE_ALL">Delete all rostered players</option></Select></label><Button variant="danger" className="mt-3 w-full" disabled={pending} onClick={openDelete}>Delete session</Button></div></div></div></div>{(reset.isError || remove.isError || preview.isError) && <p role="alert" className="mt-4 rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(reset.error ?? remove.error ?? preview.error)}</p>}</Card></div>{confirmAction === "reset" && <DestructiveConfirmDialog title="Reset this session?" body={`Matches, scores, payments, and session statistics for ${session.name} will be permanently deleted. The roster and setup will remain.`} confirmLabel="Reset session" pending={reset.isPending} onConfirm={confirm} onClose={() => setConfirmAction(null)} />}{confirmAction === "delete" && <DestructiveConfirmDialog title={disposition === "DELETE_ALL" ? "Delete session and rostered players?" : "Delete this session?"} body={deleteBody} confirmLabel="Delete session" pending={remove.isPending || preview.isPending} error={remove.isError ? remove.error : preview.isError ? preview.error : undefined} onConfirm={confirm} onClose={() => { if (!remove.isPending) setConfirmAction(null); }} />}</div>;
}

function QueueSettingsControls({ session, onReset }: { session: SessionSummary; onReset: (session: SessionSummary) => void }) {
  const [confirmOpen, setConfirmOpen] = useState(false);
  const reset = useMutation({ mutationFn: () => api.startFreshQueue(session.version), onSuccess: (updated) => { setConfirmOpen(false); onReset(updated); toast.success("Queue cleared. Ready for a fresh match."); } });
  return <Card className="border-[#f1c5b5]"><div className="flex items-start gap-3"><div className="grid size-10 place-items-center rounded-2xl bg-[#fff0e4] text-[#a74646]"><Trash2 size={19} /></div><div><h3 className="font-semibold">Start fresh queue</h3><p className="mt-1 text-sm leading-6 text-[var(--muted)]">This permanently clears players in the queue, courts, matches, scores, payments, rankings, and history. Reusable player profiles and account defaults stay available.</p><Button variant="danger" className="mt-4" disabled={reset.isPending} onClick={() => setConfirmOpen(true)}>Start fresh queue</Button></div></div>{reset.isError && <p role="alert" className="mt-4 rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(reset.error)}</p>}{confirmOpen && <DestructiveConfirmDialog title="Start fresh queue?" body="All current queue activity, including open matches, completed scores, payments, rankings, and history, will be permanently deleted. Player profiles and account defaults will remain." confirmLabel="Start fresh queue" pending={reset.isPending} onConfirm={() => reset.mutate()} onClose={() => { if (!reset.isPending) setConfirmOpen(false); }} />}</Card>;
}

function SuperAdminSettings({ user }: { user: AuthUser }) {
  const [securityOpen, setSecurityOpen] = useState(false);
  return <><Card><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-2xl bg-[#edf8f4] text-[var(--teal)]"><ShieldCheck size={19} /></div><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[var(--teal)]">Administration</p><h3 className="display mt-1 text-3xl">Shuttle Queue administration</h3><p className="mt-2 text-sm leading-6 text-[var(--muted)]">Manage your sign-in and the Queue Master and Super Admin accounts that use this queue.</p></div></div><Button variant="quiet" className="mt-4" onClick={() => setSecurityOpen(true)}><KeyRound size={15} /> Change password</Button></Card><AccountManagementView user={user} />{securityOpen && <ChangePasswordDialog onClose={() => setSecurityOpen(false)} />}</>;
}

function SettingsView(props: { session: SessionSummary; sessionId: string; user: AuthUser; onReset: (session: SessionSummary) => void; onDeleted: () => void }) {
  return <div className="space-y-5"><h2 className="sr-only">Offline settings</h2><OfflineSyncPanel accountId={props.user.id} />{props.user.role === "SUPER_ADMIN" && <SuperAdminSettings user={props.user} />}<LateArrivalSettingsCard session={props.session} sessionId={props.sessionId} /><p className="px-1 text-xs text-[var(--muted)]">“Set to now” uses server time online; offline mode uses this device’s clock.</p><QueueSettingsControls session={props.session} onReset={props.onReset} /></div>;
}

function formatHistoryDuration(seconds: number | null) {
  if (seconds === null) return "Duration unavailable";
  return `${Math.max(1, Math.round(seconds / 60))} min`;
}

function historyTeamPlayers(match: HistoryMatch, team: "A" | "B") {
  return match.participants.filter((participant) => participant.team === team).sort((a, b) => a.teamSlot - b.teamSlot);
}

function historyScoreLabel(match: HistoryMatch) {
  if (!match.score?.games.length) return "Score unavailable";
  return match.score.games.map((game) => `${game.teamAScore}–${game.teamBScore}`).join(" · ");
}

function HistoryMatchCard({ match, selectedPlayerId }: { match: HistoryMatch; selectedPlayerId?: string }) {
  const [expanded, setExpanded] = useState(false);
  const teamA = historyTeamPlayers(match, "A");
  const teamB = historyTeamPlayers(match, "B");
  const winner = match.winnerTeam ? `Team ${match.winnerTeam} won` : "Winner unavailable";
  return <article className="border-b border-[var(--line)] p-4 last:border-0"><button type="button" className="focus-ring flex w-full items-start gap-3 rounded-2xl text-left" aria-expanded={expanded} onClick={() => setExpanded((current) => !current)}><span className="mt-0.5 grid size-9 shrink-0 place-items-center rounded-full bg-[#edf8f4] text-[var(--teal)]"><HistoryIcon size={16} /></span><span className="min-w-0 flex-1"><span className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-[var(--muted)]"><span>{match.completedAt ? new Date(match.completedAt).toLocaleString() : "Completion time unavailable"}</span><span>·</span><span>{formatHistoryDuration(match.durationSeconds)}</span>{match.court && <><span>·</span><span>{match.court.name}</span></>}</span><span className="mt-2 block text-sm font-semibold"><span className={match.winnerTeam === "A" ? "text-[var(--teal)]" : ""}>{teamA.map((player) => player.displayName).join(" + ") || "Team A"}</span><span className="mx-2 text-[var(--muted)]">vs</span><span className={match.winnerTeam === "B" ? "text-[var(--teal)]" : ""}>{teamB.map((player) => player.displayName).join(" + ") || "Team B"}</span></span><span className="mt-1 block text-xs text-[var(--muted)]">{historyScoreLabel(match)} · {winner}</span></span><ChevronDown size={18} className={`mt-1 shrink-0 text-[var(--muted)] transition ${expanded ? "rotate-180" : ""}`} /></button>{expanded && <div className="mt-4 space-y-4 rounded-2xl bg-[#f7faf8] p-4"><div className="grid gap-3 sm:grid-cols-2"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--teal)]">Team A</p><div className="mt-2 space-y-2">{teamA.map((player) => <div key={player.sessionPlayerId} className={`rounded-xl border px-3 py-2 ${selectedPlayerId === player.sessionPlayerId ? "border-[var(--teal)] bg-[#edf8f4]" : "border-[var(--line)] bg-white"}`}><p className="text-sm font-semibold">{player.displayName}</p><p className="text-xs text-[var(--muted)]">{player.gender === "MALE" ? "Male" : player.gender === "FEMALE" ? "Female" : "Gender unavailable"} · {player.skillLevel ? pretty(player.skillLevel) : "Skill unavailable"}</p></div>)}</div></div><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[#a85b2b]">Team B</p><div className="mt-2 space-y-2">{teamB.map((player) => <div key={player.sessionPlayerId} className={`rounded-xl border px-3 py-2 ${selectedPlayerId === player.sessionPlayerId ? "border-[var(--teal)] bg-[#edf8f4]" : "border-[var(--line)] bg-white"}`}><p className="text-sm font-semibold">{player.displayName}</p><p className="text-xs text-[var(--muted)]">{player.gender === "MALE" ? "Male" : player.gender === "FEMALE" ? "Female" : "Gender unavailable"} · {player.skillLevel ? pretty(player.skillLevel) : "Skill unavailable"}</p></div>)}</div></div></div>{match.score?.games.length ? <div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--muted)]">Game scores</p><div className="mt-2 overflow-hidden rounded-xl border border-[var(--line)] bg-white">{match.score.games.map((game) => <div key={game.gameNumber} className="flex items-center justify-between border-b border-[var(--line)] px-3 py-2 text-sm last:border-0"><span>Game {game.gameNumber}</span><span className="font-semibold">{game.teamAScore} – {game.teamBScore}</span><span className="text-xs text-[var(--muted)]">Team {game.winnerTeam}</span></div>)}</div></div> : <p className="text-xs text-[var(--muted)]">No score revision is available for this match.</p>}</div>}</article>;
}

function PaginationControls({ pagination, onPage }: { pagination: { page: number; totalPages: number; total: number }; onPage: (page: number) => void }) {
  return <div className="flex items-center justify-between border-t border-[var(--line)] px-4 py-3"><p className="text-xs text-[var(--muted)]">Page {pagination.page} of {pagination.totalPages} · {pagination.total} matches</p><div className="flex gap-2"><Button variant="quiet" className="px-3" aria-label="Previous page" disabled={pagination.page <= 1} onClick={() => onPage(Math.max(1, pagination.page - 1))}><ArrowLeft size={15} /></Button><Button variant="quiet" className="px-3" aria-label="Next page" disabled={pagination.page >= pagination.totalPages} onClick={() => onPage(Math.min(pagination.totalPages, pagination.page + 1))}><ArrowRight size={15} /></Button></div></div>;
}

function FeesView({ sessionId }: { sessionId: string }) {
  const queryClient = useQueryClient();
  const feeQuery = useQuery({ queryKey: ["fees", sessionId], queryFn: () => api.fees(sessionId) });
  const paymentsQuery = useQuery({ queryKey: ["payments", sessionId], queryFn: () => api.payments(sessionId) });
  const [mode, setMode] = useState<"FIXED_PER_PLAYER" | "EQUAL_SPLIT">("FIXED_PER_PLAYER");
  const [configAmount, setConfigAmount] = useState("");
  const [selectedPlayerId, setSelectedPlayerId] = useState("");
  const [paymentKind, setPaymentKind] = useState<"COLLECTION" | "WAIVER">("COLLECTION");
  const [paymentMethod, setPaymentMethod] = useState<"CASH" | "EWALLET" | "OTHER">("CASH");
  const [paymentAmount, setPaymentAmount] = useState("");
  const [paymentFilter, setPaymentFilter] = useState<FeePaymentFilter>("ALL");
  const fee = feeQuery.data;
  const payments = paymentsQuery.data ?? EMPTY_PAYMENTS;
  const currency = fee?.config?.currencyCode ?? "PHP";
  const payablePlayers = useMemo(() => (fee?.players ?? []).filter((player) => player.outstandingMinor > 0), [fee]);
  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    if (!fee) return;
    const nextMode = fee.config?.mode ?? "FIXED_PER_PLAYER";
    setMode(nextMode);
    setConfigAmount(String(((nextMode === "EQUAL_SPLIT" ? fee.config?.expectedSessionCostMinor : fee.config?.fixedAmountPerPlayerMinor) ?? 0) / 100));
    if (!payablePlayers.some((player) => feePlayerId(player) === selectedPlayerId)) setSelectedPlayerId(payablePlayers[0] ? feePlayerId(payablePlayers[0]) : "");
  }, [fee, payablePlayers, selectedPlayerId]);
  /* eslint-enable react-hooks/set-state-in-effect */
  const refresh = () => { queryClient.invalidateQueries({ queryKey: ["fees", sessionId] }); queryClient.invalidateQueries({ queryKey: ["payments", sessionId] }); queryClient.invalidateQueries({ queryKey: ["sessionPlayers", sessionId] }); };
  const configure = useMutation({ mutationFn: () => { const amountMinor = Math.round(Number(configAmount) * 100); if (!Number.isFinite(amountMinor) || amountMinor < 0) throw new Error("Enter a valid non-negative amount."); return api.updateFeeConfig(sessionId, mode === "FIXED_PER_PLAYER" ? { mode, fixedAmountPerPlayerMinor: amountMinor } : { mode, expectedSessionCostMinor: amountMinor }); }, onSuccess: () => { refresh(); toast.success("Fee allocation updated."); } });
  const collect = useMutation({ mutationFn: () => { const amountMinor = Math.round(Number(paymentAmount) * 100); if (!selectedPlayerId) throw new Error("Select a player."); if (!Number.isFinite(amountMinor) || amountMinor <= 0) throw new Error("Enter a positive amount."); return api.createPayment(sessionId, { sessionPlayerId: selectedPlayerId, kind: paymentKind, amountMinor, ...(paymentKind === "COLLECTION" ? { method: paymentMethod } : {}) }); }, onSuccess: () => { setPaymentAmount(""); refresh(); toast.success(paymentKind === "COLLECTION" ? "Payment recorded." : "Waiver recorded."); } });
  const collectionByMethod = (method: Payment["method"]) => payments.filter((payment) => payment.kind === "COLLECTION" && payment.method === method).reduce((sum, payment) => sum + payment.amountMinor, 0);
  const collectionTotal = useCallback((player: NonNullable<typeof fee>["players"][number]) => Object.values(player.collectionByMethodMinor).reduce((sum, amount) => sum + amount, 0), []);
  const filteredPlayers = useMemo(() => (fee?.players ?? []).filter((player) => paymentFilter === "ALL" ? collectionTotal(player) > 0 : player.collectionByMethodMinor[paymentFilter as PaymentMethod] > 0), [fee, paymentFilter, collectionTotal]);
  const filteredPayments = useMemo(() => payments.filter((payment) => paymentFilter === "ALL" || (payment.kind === "COLLECTION" && payment.method === paymentFilter)), [payments, paymentFilter]);
  const filterLabel = paymentFilter === "ALL" ? "all payment methods" : paymentFilterLabel(paymentFilter);
  return <div className="space-y-5">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end">
      <div><p className="text-sm text-[var(--muted)]">Cash and e-wallet reconciliation</p><h2 className="display text-4xl">Keep fees accounted for.</h2></div>
      {fee && <Badge tone={fee.outstandingMinor === 0 ? "teal" : "orange"}>{formatMoney(fee.outstandingMinor, currency)} outstanding</Badge>}
    </div>
    {feeQuery.isError || paymentsQuery.isError ? <p role="alert" className="rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">{errorMessage(feeQuery.error ?? paymentsQuery.error)}</p> : <>
      <div className="grid gap-3 sm:grid-cols-4">{[["Expected", fee?.expectedMinor ?? 0], ["Collected", fee?.collectedMinor ?? 0], ["Outstanding", fee?.outstandingMinor ?? 0], ["Payments", fee?.paymentCount ?? 0]].map(([label, value]) => <Card key={String(label)} className="p-4"><p className="text-xs uppercase tracking-[0.12em] text-[var(--muted)]">{label}</p><p className="mt-2 text-xl font-semibold">{label === "Payments" ? value : formatMoney(Number(value), currency)}</p></Card>)}</div>
      <Card className="p-4"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--teal)]">Payment method filter</p><p className="mt-1 text-sm text-[var(--muted)]">Filter the player summary and ledger together.</p></div><div className="flex flex-wrap gap-2" role="group" aria-label="Filter payments by method">{FEE_PAYMENT_FILTERS.map(([label, value]) => <button key={value} type="button" aria-pressed={paymentFilter === value} className={"focus-ring rounded-full border px-3 py-2 text-sm font-semibold transition " + (paymentFilter === value ? "border-[var(--teal)] bg-[var(--teal)] text-white" : "border-[var(--line)] bg-white text-[var(--muted)] hover:border-[var(--teal)] hover:text-[var(--ink)]")} onClick={() => setPaymentFilter(value)}>{label}</button>)}</div></div></Card>
      <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_380px]">
        <Card><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--teal)]">Allocation</p><h3 className="display mt-1 text-3xl">Set the current queue fee.</h3><p className="mt-2 text-sm leading-6 text-[var(--muted)]">Amounts are stored in minor currency units and allocated only to checked-in players.</p></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><label className="block text-sm font-semibold">Fee mode<Select value={mode} onChange={(event) => setMode(event.target.value as typeof mode)}><option value="FIXED_PER_PLAYER">Fixed per player</option><option value="EQUAL_SPLIT">Equal split</option></Select></label><label className="block text-sm font-semibold">{mode === "EQUAL_SPLIT" ? "Expected queue total" : "Amount per player"}<Input inputMode="decimal" value={configAmount} onChange={(event) => setConfigAmount(event.target.value.replace(/[^0-9.]/g, ""))} placeholder="0.00" /></label></div>{configure.isError && <p role="alert" className="mt-3 rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(configure.error)}</p>}<Button className="mt-4" onClick={() => configure.mutate()} disabled={configure.isPending}>{configure.isPending ? "Saving…" : "Save allocation"}</Button><div className="mt-7 border-t border-[var(--line)] pt-5"><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--muted)]">By method</p><div className="mt-3 grid gap-2 sm:grid-cols-3">{([["Cash", "CASH"], ["E-wallet", "EWALLET"], ["Other", "OTHER"]] as const).map(([label, method]) => <div key={method} className="rounded-2xl bg-[#f7faf8] p-3"><p className="text-xs text-[var(--muted)]">{label}</p><p className="mt-1 font-semibold">{formatMoney(collectionByMethod(method), currency)}</p></div>)}</div></div></Card>
        <Card><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--orange)]">Record</p><h3 className="display mt-1 text-3xl">Log a payment.</h3><div className="mt-5 space-y-3"><label className="block text-sm font-semibold">Player<Select value={selectedPlayerId} onChange={(event) => setSelectedPlayerId(event.target.value)}><option value="">Select player</option>{payablePlayers.map((player) => <option key={feePlayerId(player)} value={feePlayerId(player)}>{player.displayName} · due {formatMoney(player.outstandingMinor, currency)}</option>)}</Select></label><label className="block text-sm font-semibold">Entry type<Select value={paymentKind} onChange={(event) => setPaymentKind(event.target.value as typeof paymentKind)}><option value="COLLECTION">Collection</option><option value="WAIVER">Waiver</option></Select></label>{paymentKind === "COLLECTION" && <label className="block text-sm font-semibold">Method<Select value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value as typeof paymentMethod)}><option value="CASH">Cash</option><option value="EWALLET">E-wallet</option><option value="OTHER">Other</option></Select></label>}<label className="block text-sm font-semibold">Amount<Input inputMode="decimal" value={paymentAmount} onChange={(event) => setPaymentAmount(event.target.value.replace(/[^0-9.]/g, ""))} placeholder="0.00" /></label>{collect.isError && <p role="alert" className="rounded-2xl bg-[#fff0e4] px-3 py-2 text-sm text-[#8d4824]">{errorMessage(collect.error)}</p>}<Button className="w-full" onClick={() => collect.mutate()} disabled={collect.isPending || !payablePlayers.length}>{collect.isPending ? "Recording…" : paymentKind === "COLLECTION" ? "Record collection" : "Record waiver"}</Button></div></Card>
      </div>
      <Card className="overflow-hidden p-0"><div className="border-b border-[var(--line)] px-4 py-3"><p className="font-semibold">Players by payment method</p><p className="mt-1 text-xs text-[var(--muted)]">{filteredPlayers.length} player{filteredPlayers.length === 1 ? "" : "s"} with {filterLabel}</p></div>{filteredPlayers.length === 0 ? <p className="p-4 text-sm text-[var(--muted)]">No players have a matching collection yet.</p> : <div>{filteredPlayers.map((player) => { const total = collectionTotal(player); const amount = paymentFilter === "ALL" ? total : player.collectionByMethodMinor[paymentFilter as PaymentMethod]; return <div key={feePlayerId(player)} className="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--line)] px-4 py-3 last:border-0"><div><p className="font-semibold">{player.displayName}</p><p className="text-xs text-[var(--muted)]">{formatMoney(amount, currency)} collected{paymentFilter !== "ALL" ? " via " + paymentFilterLabel(paymentFilter) : ""}</p></div><div className="flex flex-wrap justify-end gap-1.5">{paymentFilter === "ALL" ? FEE_PAYMENT_FILTERS.slice(1).map(([label, method]) => player.collectionByMethodMinor[method as PaymentMethod] > 0 ? <Badge key={method} tone="gray">{label}: {formatMoney(player.collectionByMethodMinor[method as PaymentMethod], currency)}</Badge> : null) : <Badge tone="teal">{paymentFilterLabel(paymentFilter)}</Badge>}</div></div>; })}</div>}</Card>
      <Card className="overflow-hidden p-0"><div className="border-b border-[var(--line)] px-4 py-3"><p className="font-semibold">Recent ledger entries</p><p className="mt-1 text-xs text-[var(--muted)]">{filteredPayments.length} entr{filteredPayments.length === 1 ? "y" : "ies"} for {filterLabel}. Each collection request uses an idempotency key so a retry cannot double-count it.</p></div>{filteredPayments.length === 0 ? <p className="p-4 text-sm text-[var(--muted)]">{paymentFilter === "ALL" ? "No payments recorded yet." : "No " + paymentFilterLabel(paymentFilter).toLowerCase() + " payments recorded yet."}</p> : <div>{filteredPayments.slice(0, 50).map((payment) => <div key={payment.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--line)] px-4 py-3 last:border-0"><div><p className="font-semibold">{fee?.players.find((player) => player.sessionPlayerId === payment.sessionPlayerId)?.displayName ?? "Player"}</p><p className="text-xs text-[var(--muted)]">{pretty(payment.kind)}{payment.method ? " · " + paymentFilterLabel(payment.method) : ""} · {new Date(payment.occurredAt).toLocaleString()}</p></div><p className="font-semibold">{formatMoney(payment.amountMinor, currency)}</p></div>)}</div>}</Card>
    </>}
  </div>;
}

function HistoryView({ sessionId }: { sessionId: string }) {
  const [page, setPage] = useState(1); const [search, setSearch] = useState("");
  const historyQuery = useQuery({ queryKey: ["history", sessionId, page, search], queryFn: () => api.history(sessionId, page, 15, search) }); const history = historyQuery.data;
  return <div className="space-y-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm text-[var(--muted)]">Finished games</p><h2 className="display text-4xl">The queue log.</h2></div>{history?.pagination && <Badge tone="teal">{history.pagination.total} completed</Badge>}</div><Card className="overflow-hidden p-0"><div className="border-b border-[var(--line)] p-4"><label className="relative block"><Search size={16} className="absolute left-3 top-3 text-[var(--muted)]" /><Input className="pl-9" value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Search by player name" aria-label="Search history by player name" /></label></div>{historyQuery.isPending ? <div className="space-y-3 p-4"><div className="h-24 animate-pulse rounded-2xl bg-[#f1f5f2]" /><div className="h-24 animate-pulse rounded-2xl bg-[#f1f5f2]" /></div> : historyQuery.isError ? <p role="alert" className="p-4 text-sm text-[#8d4824]">{errorMessage(historyQuery.error)}</p> : !history?.items.length ? <div className="p-4"><EmptyState icon={HistoryIcon} title={search ? "No matching games" : "No finished games yet"} body={search ? "Try another player name or clear the search." : "Completed matches will appear here after score entry."} /></div> : <div>{history.items.map((match) => <HistoryMatchCard key={match.id} match={match} />)}</div>}{history?.pagination && history.pagination.total > 0 && <PaginationControls pagination={history.pagination} onPage={setPage} />}</Card></div>;
}

function PlayerHistoryDetails({ sessionId, ranking }: { sessionId: string; ranking: Ranking }) {
  const playerId = ranking.queuePlayerId ?? ranking.sessionPlayerId;
  const [page, setPage] = useState(1); const playerQuery = useQuery({ queryKey: ["playerHistory", sessionId, playerId, page], queryFn: () => api.playerHistory(sessionId, playerId, page, 15) }); const data = playerQuery.data as PlayerHistoryResponse | undefined;
  if (playerQuery.isPending) return <div className="border-t border-[var(--line)] bg-[#fbfdfb] p-4 text-sm text-[var(--muted)]">Loading {ranking.player}’s history…</div>;
  if (playerQuery.isError) return <p role="alert" className="border-t border-[var(--line)] bg-[#fff0e4] p-4 text-sm text-[#8d4824]">{errorMessage(playerQuery.error)}</p>;
  if (!data) return null;
  const stats = data.stats;
  return <div className="border-t border-[var(--line)] bg-[#fbfdfb] p-4"><div className="flex flex-wrap items-center gap-2"><Badge tone="teal">{data.player.gender === "MALE" ? "Male" : "Female"}</Badge><Badge tone="gray">{pretty(data.player.skillLevel)}</Badge></div><div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4"><div className="rounded-xl bg-white p-3"><p className="text-xs text-[var(--muted)]">Matches</p><p className="mt-1 font-semibold">{stats.matchesPlayed}</p></div><div className="rounded-xl bg-white p-3"><p className="text-xs text-[var(--muted)]">Record</p><p className="mt-1 font-semibold">{stats.wins}W / {stats.losses}L</p></div><div className="rounded-xl bg-white p-3"><p className="text-xs text-[var(--muted)]">Win rate</p><p className="mt-1 font-semibold">{(stats.winRateBasisPoints / 100).toFixed(0)}%</p></div><div className="rounded-xl bg-white p-3"><p className="text-xs text-[var(--muted)]">Points</p><p className="mt-1 font-semibold">{stats.pointsFor}–{stats.pointsAgainst}</p></div><div className="rounded-xl bg-white p-3"><p className="text-xs text-[var(--muted)]">Differential</p><p className="mt-1 font-semibold">{stats.pointDifferential > 0 ? "+" : ""}{stats.pointDifferential}</p></div><div className="rounded-xl bg-white p-3"><p className="text-xs text-[var(--muted)]">Avg duration</p><p className="mt-1 font-semibold">{formatHistoryDuration(stats.averageDurationSeconds)}</p></div><div className="rounded-xl bg-white p-3"><p className="text-xs text-[var(--muted)]">Top partner</p><p className="mt-1 truncate font-semibold">{stats.mostPlayedPartner ? `${stats.mostPlayedPartner.displayName} (${stats.mostPlayedPartner.count})` : "—"}</p></div><div className="rounded-xl bg-white p-3"><p className="text-xs text-[var(--muted)]">Top opponent</p><p className="mt-1 truncate font-semibold">{stats.mostPlayedOpponent ? `${stats.mostPlayedOpponent.displayName} (${stats.mostPlayedOpponent.count})` : "—"}</p></div></div><div className="mt-4 overflow-hidden rounded-2xl border border-[var(--line)] bg-white">{data.items.length ? data.items.map((match) => <HistoryMatchCard key={match.id} match={match} selectedPlayerId={playerId} />) : <p className="p-4 text-sm text-[var(--muted)]">No completed games for this player yet.</p>}{data.pagination.total > 0 && <PaginationControls pagination={data.pagination} onPage={setPage} />}</div></div>;
}

function RankingsView({ sessionId }: { sessionId: string }) {
  const rankingsQuery = useQuery({ queryKey: ["rankings", sessionId], queryFn: () => api.rankings(sessionId) }); const rankings = rankingsQuery.data ?? []; const [expandedId, setExpandedId] = useState<string | null>(null);
  return <div className="space-y-5"><div><p className="text-sm text-[var(--muted)]">Current queue rankings</p><h2 className="display text-4xl">Results that stay useful.</h2></div><Card className="overflow-hidden p-0">{rankingsQuery.isPending ? <div className="p-6 text-sm text-[var(--muted)]">Loading rankings…</div> : rankingsQuery.isError ? <p role="alert" className="p-4 text-sm text-[#8d4824]">{errorMessage(rankingsQuery.error)}</p> : rankings.length === 0 ? <div className="p-4"><EmptyState icon={Trophy} title="No results yet" body="Finish a match and the leaderboard will appear here." /></div> : <div>{rankings.map((row) => { const rankingId = row.queuePlayerId ?? row.sessionPlayerId; return <div key={rankingId} className="border-b border-[var(--line)] last:border-0"><button type="button" className="focus-ring flex w-full items-center gap-4 px-4 py-4 text-left" aria-expanded={expandedId === rankingId} onClick={() => setExpandedId((current) => current === rankingId ? null : rankingId)}><span className="grid size-9 place-items-center rounded-full bg-[#edf8f4] text-sm font-bold text-[var(--teal)]">{row.rank}</span><div className="min-w-0 flex-1"><p className="truncate font-semibold">{row.player}</p><p className="text-xs text-[var(--muted)]">{row.gender === "MALE" ? "Male" : "Female"} · {pretty(row.skillLevel)} · {row.matchesPlayed} games · {row.wins}W / {row.losses}L</p></div><div className="text-right"><p className="font-semibold">{(row.winRateBasisPoints / 100).toFixed(0)}%</p><p className="text-xs text-[var(--muted)]">win rate</p></div><ChevronDown size={18} className={`shrink-0 text-[var(--muted)] transition ${expandedId === rankingId ? "rotate-180" : ""}`} /></button>{expandedId === rankingId && <PlayerHistoryDetails sessionId={sessionId} ranking={row} />}</div>; })}</div>}</Card></div>;
}

function SessionSwitcher({ sessions, active, onChange, onCreate }: { sessions: SessionSummary[]; active: SessionSummary | undefined; onChange: (id: string) => void; onCreate: () => void }) {
  return <div className="flex min-w-0 items-center gap-2"><div className="relative min-w-0"><select aria-label="Active session" className="focus-ring max-w-[220px] appearance-none rounded-2xl border border-[var(--line)] bg-white py-2 pl-3 pr-8 text-sm font-semibold outline-none" value={active?.id ?? ""} onChange={(event) => onChange(event.target.value)}>{sessions.map((session) => <option key={session.id} value={session.id}>{session.name}</option>)}</select><ChevronDown className="pointer-events-none absolute right-2 top-2.5 text-[var(--muted)]" size={15} /></div><Button variant="quiet" className="px-3" title="Create session" aria-label="Create session" onClick={onCreate}><Plus size={16} /></Button></div>;
}

function QueueWorkspaceShell({ user, onLogout }: { user: AuthUser; onLogout: () => void }) {
  const queryClient = useQueryClient();
  const [sessionId, setSessionId] = useState("");
  const [tab, setTab] = useState<Tab>("live");
  const sessionsQuery = useQuery({ queryKey: ["sessions"], queryFn: api.sessions });
  const [newSessionName, setNewSessionName] = useState("");
  const sessions = sessionsQuery.data ?? [];
  const active = sessions.find((session) => session.id === sessionId) ?? sessions[0];
  const create = useMutation({ mutationFn: () => api.createSession({ name: newSessionName.trim() }), onSuccess: (session) => { setNewSessionName(""); setSessionId(session.id); queryClient.invalidateQueries({ queryKey: ["sessions"] }); toast.success("Draft session created."); } });
  const start = useMutation({ mutationFn: () => active ? api.startSession(active.id, active.version) : Promise.reject(new Error("Select a session.")), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["sessions"] }); toast.success("Session started."); } });
  if (sessionsQuery.isPending) return <main className="grid min-h-screen place-items-center text-sm text-[var(--muted)]">Loading your sessions…</main>;
  const refreshSessionData = () => { queryClient.invalidateQueries({ queryKey: ["sessions"] }); queryClient.invalidateQueries({ queryKey: ["sessionPlayers", active?.id] }); queryClient.invalidateQueries({ queryKey: ["queue", active?.id] }); queryClient.invalidateQueries({ queryKey: ["courts", active?.id] }); queryClient.invalidateQueries({ queryKey: ["matches", active?.id] }); queryClient.invalidateQueries({ queryKey: ["history", active?.id] }); queryClient.invalidateQueries({ queryKey: ["playerHistory", active?.id] }); queryClient.invalidateQueries({ queryKey: ["rankings", active?.id] }); queryClient.invalidateQueries({ queryKey: ["rankings", "career"] }); };
  return <main className="min-h-screen"><header className="sticky top-0 z-30 border-b border-[var(--line)] bg-[var(--paper)]/95 backdrop-blur"><div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3 px-4 py-3 sm:px-6"><div className="flex min-w-0 items-center gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-2xl bg-[var(--teal)] text-white"><Activity size={20} /></div><div className="hidden min-w-0 sm:block"><p className="truncate text-sm font-bold">Shuttle Queue</p><p className="truncate text-xs text-[var(--muted)]">{user.username}</p></div></div><SessionSwitcher sessions={sessions} active={active} onChange={setSessionId} onCreate={() => { const value = window.prompt("Name this session"); if (value?.trim()) { setNewSessionName(value.trim()); setTimeout(() => create.mutate(), 0); } }} /><Button variant="quiet" className="px-3" title="Sign out" aria-label="Sign out" onClick={onLogout}><LogOut size={16} /></Button></div><div className="mx-auto flex max-w-7xl gap-1 overflow-x-auto px-4 pb-3 sm:px-6">{(Object.keys(tabLabels) as Tab[]).map((key) => <button key={key} className={`focus-ring flex shrink-0 items-center gap-2 rounded-full px-4 py-2 text-sm font-semibold transition ${tab === key ? "bg-[var(--teal)] text-white" : "text-[var(--muted)] hover:bg-white hover:text-[var(--ink)]"}`} onClick={() => setTab(key)}>{key === "live" ? <Activity size={15} /> : key === "queue" ? <UsersRound size={15} /> : key === "players" ? <UsersRound size={15} /> : key === "settings" ? <Settings2 size={15} /> : key === "history" ? <HistoryIcon size={15} /> : key === "fees" ? <Wallet size={15} /> : <Trophy size={15} />}{tabLabels[key]}</button>)}</div></header><div className="mx-auto max-w-7xl px-4 py-7 sm:px-6 sm:py-10">{!active ? <EmptyState icon={Sparkles} title="Create your first session" body="Sessions hold the courts, queue, and rankings for one day." action={<Button onClick={() => { const value = window.prompt("Name this session"); if (value?.trim()) { setNewSessionName(value.trim()); setTimeout(() => create.mutate(), 0); } }}><Plus size={16} /> New session</Button>} /> : tab === "live" ? <LiveView session={active} sessionId={active.id} onStartSession={() => start.mutate()} /> : tab === "queue" ? <QueueView sessionId={active.id} /> : tab === "players" ? <PlayersView key={active.id} sessionId={active.id} /> : tab === "history" ? <HistoryView sessionId={active.id} /> : tab === "fees" ? <FeesView key={active.id} sessionId={active.id} /> : tab === "settings" ? <SettingsView session={active} sessionId={active.id} user={user} onReset={(updated) => { queryClient.setQueryData<SessionSummary[]>(["sessions"], (current = []) => current.map((item) => item.id === updated.id ? updated : item)); refreshSessionData(); setTab("live"); }} onDeleted={() => { queryClient.setQueryData<SessionSummary[]>(["sessions"], (current = []) => current.filter((item) => item.id !== active.id)); setSessionId(""); setTab("live"); queryClient.removeQueries({ queryKey: ["sessionPlayers", active.id] }); queryClient.removeQueries({ queryKey: ["queue", active.id] }); queryClient.removeQueries({ queryKey: ["courts", active.id] }); queryClient.removeQueries({ queryKey: ["matches", active.id] }); queryClient.removeQueries({ queryKey: ["history", active.id] }); queryClient.removeQueries({ queryKey: ["playerHistory", active.id] }); queryClient.removeQueries({ queryKey: ["rankings", active.id] }); queryClient.invalidateQueries({ queryKey: ["sessions"] }); }} /> : <RankingsView sessionId={active.id} />}{start.isError && <p role="alert" className="mt-4 rounded-2xl bg-[#fff0e4] px-4 py-3 text-sm text-[#8d4824]">{errorMessage(start.error)}</p>}</div></main>;
}

function QueueWorkspaceShellV2({ user, onLogout }: { user: AuthUser; onLogout: () => void }) {
  const queryClient = useQueryClient();
  const [tab, setTab] = useState<Tab>("live");
  const workspaceQuery = useQuery({ queryKey: ["workspace"], queryFn: api.workspace });
  const active = workspaceQuery.data;
  const workspaceId = "workspace";
  if (workspaceQuery.isPending) return <main className="grid min-h-screen place-items-center text-sm text-[var(--muted)]">Loading your queueâ€¦</main>;
  if (!active) return <main className="grid min-h-screen place-items-center text-sm text-[#8d4824]">The current queue could not be loaded.</main>;
  const refreshQueueData = () => { queryClient.invalidateQueries({ queryKey: ["workspace"] }); for (const key of ["sessionPlayers", "queue", "courts", "matches", "history", "playerHistory", "rankings", "fees", "payments"]) queryClient.invalidateQueries({ queryKey: [key, workspaceId] }); };
  return <main className="min-h-screen"><header className="sticky top-0 z-30 border-b border-[var(--line)] bg-[var(--paper)]/95 backdrop-blur"><div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3 px-4 py-3 sm:px-6"><div className="flex min-w-0 items-center gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-2xl bg-[var(--teal)] text-white"><Activity size={20} /></div><div className="hidden min-w-0 sm:block"><p className="truncate text-sm font-bold">Shuttle Queue</p><p className="truncate text-xs text-[var(--muted)]">{user.username}</p></div></div><h1 className="text-sm font-semibold text-[var(--muted)]">Current queue</h1><Button variant="quiet" className="px-3" title="Sign out" aria-label="Sign out" onClick={onLogout}><LogOut size={16} /></Button></div><div className="mx-auto flex max-w-7xl gap-1 overflow-x-auto px-4 pb-3 sm:px-6">{(Object.keys(tabLabels) as Tab[]).map((key) => <button key={key} className={`focus-ring flex shrink-0 items-center gap-2 rounded-full px-4 py-2 text-sm font-semibold transition ${tab === key ? "bg-[var(--teal)] text-white" : "text-[var(--muted)] hover:bg-white hover:text-[var(--ink)]"}`} onClick={() => setTab(key)}>{key === "live" ? <Activity size={15} /> : key === "queue" ? <UsersRound size={15} /> : key === "players" ? <UsersRound size={15} /> : key === "settings" ? <Settings2 size={15} /> : key === "history" ? <HistoryIcon size={15} /> : key === "fees" ? <Wallet size={15} /> : <Trophy size={15} />}{tabLabels[key]}</button>)}</div></header><div className="mx-auto max-w-7xl px-4 py-7 sm:px-6 sm:py-10">{tab === "live" ? <LiveView session={active} sessionId={workspaceId} onStartSession={() => undefined} /> : tab === "queue" ? <QueueView sessionId={workspaceId} /> : tab === "players" ? <PlayersView key={workspaceId} sessionId={workspaceId} /> : tab === "history" ? <HistoryView sessionId={workspaceId} /> : tab === "fees" ? <FeesView key={workspaceId} sessionId={workspaceId} /> : tab === "settings" ? <SettingsView session={active} sessionId={workspaceId} user={user} onReset={() => { refreshQueueData(); setTab("live"); }} onDeleted={() => { refreshQueueData(); setTab("live"); }} /> : <RankingsView sessionId={workspaceId} />}</div></main>;
}

function SuperAdminShell({ user, onLogout }: { user: AuthUser; onLogout: () => void }) {
  return <QueueWorkspaceShellV2 user={user} onLogout={onLogout} />;
}

function AppShell({ user, onLogout }: { user: AuthUser; onLogout: () => void }) {
  return user.role === "SUPER_ADMIN" ? <SuperAdminShell user={user} onLogout={onLogout} /> : <QueueMasterShell user={user} onLogout={onLogout} />;
}

function QueueMasterShell({ user, onLogout }: { user: AuthUser; onLogout: () => void }) {
  const [securityOpen, setSecurityOpen] = useState(false);
  return <div><header className="sticky top-0 z-40 flex items-center justify-between gap-3 border-b border-[var(--line)] bg-white px-4 py-2 sm:px-6"><div className="flex items-center gap-2 text-sm"><Badge tone="gray">Queue Master</Badge><span className="hidden text-[var(--muted)] sm:inline">{user.username}</span></div><Button variant="quiet" className="px-3 py-1.5 text-xs" title="Change password" aria-label="Change password" onClick={() => setSecurityOpen(true)}><KeyRound size={15} /> <span className="hidden sm:inline">Change password</span></Button></header><QueueWorkspaceShellV2 user={user} onLogout={onLogout} />{securityOpen && <ChangePasswordDialog onClose={() => setSecurityOpen(false)} />}</div>;
}

export default function HomePage() {
  const [authUser, setAuthUser] = useState<AuthUser | null>(null);
  const [retainedUser, setRetainedUser] = useState<AuthUser | null>(null);
  const me = useQuery({ queryKey: ["me"], queryFn: api.me, retry: false, enabled: !authUser });
  const queryClient = useQueryClient();
  useEffect(() => { let signedOut = false; try { signedOut = window.sessionStorage.getItem("shuttle-queue-offline-signed-out") === "1"; } catch { /* ignore storage access failures */ } if (!authUser && me.isError && !signedOut) void retainedProfile().then((profile) => { if (profile) setRetainedUser({ id: profile.accountId, username: profile.username, role: profile.role === "SUPER_ADMIN" ? "SUPER_ADMIN" : "QUEUE_MASTER" }); }); }, [authUser, me.isError]);
  const user = authUser ?? me.data?.user ?? retainedUser;
  if (!user && me.isPending && !me.isFetched) return <main className="grid min-h-screen place-items-center text-sm text-[var(--muted)]">Loading Shuttle Queue…</main>;
  if (!user) return <LoginScreen onLoggedIn={setAuthUser} />;
  return <OfflineBootstrap user={user} onLogout={async () => { const remove = window.confirm("Sign out now? Select OK to remove downloaded data from this browser, or Cancel to keep it for offline access."); if (remove) await clearAccountData(user.id).catch(() => undefined); try { window.sessionStorage.setItem("shuttle-queue-offline-signed-out", "1"); } catch { /* ignore storage access failures */ } try { await api.logout(); } catch { /* offline sign-out is local until reconnect */ } setAuthUser(null); setRetainedUser(null); queryClient.clear(); }} />;
}
